"""Approximate responses to document starts and text-formatting characters.

Bare carriage returns (terminal redraws) are positive, especially when repeated.
NUL tokens and repeated middle dots are negative; long blank-line tokens are
positive.  At document starts, indentation, newlines and tokens with four or
more capitals have a stronger negative offset than ordinary text.  A short hash heading
marker is an exception.  Title fields, header separators and blank-line bursts
have separate formatting rules.  A narrow numeric case is the second digit
of a document-initial 12.  Most lexical variation is omitted.
"""
import unicodedata

READS = ()


def start_value(text):
    if text.count(' ') >= 3:
        return -0.83
    if text.startswith('\n'):
        return -0.65
    if '#' in text:
        if len(text) > 4:
            return -0.84
        punctuation = sum(unicodedata.category(c).startswith('P') for c in text)
        return 0.30 if punctuation <= 1 else -0.19
    if sum(c.isupper() for c in text) >= 4:
        return -0.63
    return -0.11 if len(text) >= 12 else -0.24


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        position, run, previous = 0, 0, ''
        title = text == 'Title'
        frontmatter = text.startswith('---')
        heading = text.startswith('#')
    else:
        _, position, run, previous, title, frontmatter, heading = carry
        position += 1
    run = run + 1 if text == '\r' else 0
    newlines = text.count('\n')
    marker = text.strip()

    if position == 1 and previous == '1' and text == '2':
        value = 2.85
    elif title and first:
        value = 0.67
    elif title and position == 1 and text == ':':
        value = 0.52
    elif title and position == 2 and text == ' To':
        value = -0.89
    elif title and marker == '[':
        value = -10.2 if position == 2 else -2.5
    elif title and newlines:
        value = -0.95
    elif marker == '[' and previous.strip() in ('##', '###', '####'):
        value = -2.2 if position == 1 else -0.5
    elif text == '\x00':
        value = -3.26 if first else -0.11
    elif run:
        value = 0.29 if run == 1 else 0.64 if run <= 8 else 0.53
    elif text.count('\r') >= 2 and newlines <= 1:
        value = min(1.5, 0.38 * text.count('\r'))
    elif text.count('·') >= 2:
        value = -0.27
    elif first:
        value = start_value(text)
    elif marker == '---' and newlines:
        closes_header = frontmatter or (
            heading and position < 32 and previous.endswith('\n'))
        value = 1.4 if closes_header else 0.0024
        frontmatter = False
    elif (position <= 3 and len(marker) >= 6 and set(marker) == {'='}
          and (previous.strip() == '#' or set(previous.strip()) == {'='})):
        value = 1.5 if previous.strip() == '#' else 1.0
    elif newlines >= 4:
        if newlines >= 12:
            value = 1.4
        else:
            value = 0.9 if previous.endswith('\n') else 0.1 * (newlines - 3)
    elif '[' in text:
        value = 0.033
    else:
        value = 0.0024
    title = title and not newlines and (position != 1 or text == ':')
    return (doc, position, run, text, title, frontmatter, heading), value

"""A partial lexical predictor, dominated by the information-entry sense of FORM.

Forms in application/contact/HTML contexts receive a large positive response;
abstract noun uses receive less, and likely verb uses nearly none. Smaller
rules cover manner, difficulty and correctness words, recency, numeric suffixes,
prime marks, test summaries, paired middle dots and an initial Title: header.
Unmodelled responses are zero. A bounded text tail resets at document breaks.
"""
import re

READS = ()
FORM = re.compile(r'^[\s._/(<\"\'-]*(form|forms)$', re.I)
ENTRY = re.compile(
    r'\b(fill(?:ing|ed)?|contact|application|submit(?:ted)?|submission|'
    r'html|input|widget|registration|register|login|signup|validate|'
    r'validation|button|fields?|google|bootstrap|tax|government)\b', re.I
)
DIRECT_ENTRY = re.compile(
    r'\b(contact|application|tax|fill(?:ing|ed)?'
    r'(?:\s+out)?(?:\s+\w+){0,3})\s*$', re.I
)
VERB_CONTEXT = re.compile(
    r'\b(to|will|can|could|would|should|may|might|must|'
    r'they|we|that|which|and)\s*$', re.I
)
PREDICATE_CONTEXT = re.compile(
    r'\b(is|are|was|were|be|been|being|seems?|looks?|quite|'
    r'absolutely|perfectly|ideally|best|not|isn.t|wasn.t|aren.t)\s*$', re.I
)
NUMBER = re.compile(r'(?<![\w.])([+-]?\d+(?:\.\d+)?)$')


def response(s, before):
    word = s.strip()
    spaced = s[:1].isspace()
    if s == ':' and before == 'Title':
        return -7.51
    if FORM.fullmatch(s):
        stem = word.lstrip('._/(<\"\'-')
        # Exclude derived words such as platform, transform and isoform.
        if not spaced and re.search(
            r'(plat|trans|uni|per|con|in|re|iso|de)$', before, re.I
        ):
            return 0.0
        if re.search(r'<\/?$', before) or s.startswith(('.', '/')):
            return 3.14
        if DIRECT_ENTRY.search(before[-100:]):
            return 4.68
        if ENTRY.search(before[-400:]):
            return 2.39
        if not spaced:
            if stem == 'forms':
                return 2.53
            return 1.08 if stem[:1].isupper() else 1.01
        if VERB_CONTEXT.search(before[-60:]):
            return 0.0
        return 1.08 if stem[:1].isupper() else 0.73
    if spaced and word in ('way', 'ways'):
        if word == 'ways':
            return 1.12
        if re.search(r'\b(same|one|easy|by the)\s*$', before, re.I):
            return 1.63
        return 0.33
    if word in ('s', 'ms', 'f', 'h', 'e') and re.search(r'\d\s*$', before):
        number = NUMBER.search(before.rstrip())
        if word == 'ms':
            return -1.83 if spaced else -2.85
        if word == 's':
            if number and '.' in number[1]:
                return -0.57 if spaced else -1.06
            return -0.25
        if not spaced and number:
            if word == 'f':
                return -0.53
            if word == 'e':
                return -0.29
            if word == 'h':
                return -0.46
    if word == '″':
        return 2.29
    if word == '′' and re.search(r'\d$', before):
        return 1.86
    if s == ' Suites' and before.endswith('Test'):
        return -1.92
    if spaced and word in (
        'right', 'correct', 'correctly', 'suitable', 'suited', 'wrong'
    ):
        if PREDICATE_CONTEXT.search(before[-60:]):
            return -0.74
        return -0.2
    if spaced and word in ('simple', 'easy', 'difficult'):
        return 0.38
    if s in (' recent', ' recently'):
        return 0.77
    if s == '··':
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (doc, (before + token)[-700:]), value

