"""Candidate v3: v2 plus a context rule for the noun 'form' (fill-in forms score higher)."""
READS = ()

VERB_BEFORE = {"to", "can", "will", "would", "could", "that", "they", "and", "may", "must", "should", "might", "we", "you", "it"}
PREDICATE_BEFORE = {"is", "was", "re", "s", "exactly", "quite", "be", "just", "you"}
FILL_IN_CONTEXT = {"application", "submit", "submission", "complete", "web", "button", "page", "print",
                   "sign", "html", "fill", "online", "contact", "visa", "apply", "registration", "subscription",
                   "input", "website", "pages"}
EASE = {"simple", "easy", "short", "understand", "large", "quick", "far", "important"}
NEG_ADJ = {"look", "whole", "few", "correct", "possible", "wrong", "bit", "extra"}


def core(token):
    return token.strip(" \t\n-./_(\"'").lower()


def has_digit(token):
    return any(ch.isdigit() for ch in token)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if prefix.position > 0 else ""
    c, pc = core(word), core(prev)
    value = 0.0
    if word.strip() == "″":
        value = 2.3
    elif word.strip() == "′":
        value = 0.8
    elif c in ("form", "forms"):
        if pc not in VERB_BEFORE:
            context = {core(s) for s in prefix.token_strings[-16:-1]}
            value = 3.0 if context & FILL_IN_CONTEXT else 1.0
    elif c == "ms" and has_digit(prev):
        value = -2.5
    elif c == "s" and has_digit(prev):
        value = -0.5
    elif c == "second" and pc in ("a", "wait", "few"):
        value = -1.0
    elif c == "ways":
        value = 1.1
    elif c == "way":
        value = 0.4
    elif c == "recent":
        value = 0.8
    elif c in EASE:
        value = 0.3
    elif c == "right":
        value = -1.6 if pc in PREDICATE_BEFORE else 0.0
    elif c in NEG_ADJ:
        value = -0.25
    return carry, value

