"""A sparse lexical possibility/ability feature, not sentence-level reasoning.

Chinese 可 and short modal compounds receive strong negative values, with
modifier-dependent strengths. English ability-suffix fragments and a few
English, German and Vietnamese modals receive smaller signed values.
Separate spelling/formatting rules cover Greek kappa-alpha, space followed
by NBSP, and doubled middle dots. Previous-token and UTF-8-tail state resets
at document boundaries; everything else is approximately silent.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', b''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    data = prefix.token_bytes[-1]
    word = token.strip()
    value = 0.0

    if word.endswith('可以'):
        modifier = word[:-2]
        value = -3.4
        if modifier in {'就', '才'}:
            value = -5.5
        elif modifier in {'都', '还', '是', '不'}:
            value = -4.6
        elif modifier in {'我', '你'}:
            value = -2.5
        elif modifier in {'我们', '您'}:
            value = -1.5
    elif word.endswith('可以了'):
        value = -2.8
    elif word in {'可靠', '可靠的', '可行', '可见', '许可'}:
        value = -1.5
    elif word.endswith('可') and len(word) <= 2:
        value = -4.9
        if word[0] in '不无均' and len(word) == 2:
            value = -7.5
        elif word == '即可':
            value = -6.2
        elif word == '方可':
            value = -3.2
        elif word == '认可':
            value = -0.3
    elif '\ufffd' in token and (tail + data).endswith('可'.encode()):
        value = -4.9
    elif word == '以' and tail.endswith('可'.encode()):
        value = -3.5
    elif token == ' \xa0':
        value = -1.5
        if previous.endswith('`'):
            value = -4.1
        elif previous and previous.isspace():
            value = -0.6
        elif previous.isdigit():
            value = -2.5
    elif token == '··':
        value = 1.3
    elif word in {'α', 'Α'} and previous.rstrip().endswith(('κ', 'Κ')):
        value = -5.5 if word == 'Α' else -3.2
    elif word == 'can':
        value = 0.05
        if previous.strip().lower() in {'you', 'it', 'they', 'she', 'which'}:
            value = 0.25
        elif previous.strip().lower() == 'we':
            value = -0.23
    elif word in {'können', 'kann'}:
        value = 0.6
    elif word == 'khả':
        value = -3.8
    elif word == 'thể':
        value = -0.9
    elif token == word and re.fullmatch('[a-z]+', word):
        if word.endswith(('izable', 'ifiable')):
            value = 2.2
        elif word in {'able', 'ible', 'ability', 'ibility'}:
            value = 0.2
        elif word.endswith(('able', 'ible')) and word not in {'table', 'stable'}:
            value = 0.4
    return (doc, token, (tail + data)[-6:]), value

"""Sparse local cues for page structure, not a general heading detector.

Predict negative values at selected HTML/XML tag names and feedback or
related-content labels.  Predict positive values at code-link hosts,
redacted addresses, and title/file metadata.  Unmatched text stays near
zero.  The state remembers one bounded line and whether a template section
has appeared; actual and escaped newlines both end a line.
The rules summarize strong training examples, leaving diffuse activity
and additional code-phrase or multilingual cues unexplained.
"""
import re

READS = ()

# Opening/closing structural and documentation tags.
TAGS = {
    'summary': (-3.0, -4.3),
    'script': (-2.7, -3.3),
    'style': (-3.7, -4.0),
    'body': (-1.6, -2.7),
    'head': (-1.0, -3.0),
    'form': (-2.5, -3.1),
    'small': (-2.2, -2.1),
    'footer': (-1.0, -1.9),
    'article': (-0.8, -1.0),
    'details': (-0.8, -0.9),
    'returns': (0.0, -1.1),
    'remarks': (-1.5, -2.5),
    'configuration': (-1.9, -3.2),
    'select': (-1.2, -1.5),
}
FEEDBACK = {'Comments', 'Answers', 'Responses', 'Reviews', 'thoughts'}
RELATED = {'questions', 'topics', 'documents', 'tutorials', 'stories', 'posts'}
HOSTS = {'github', 'developer', 'developers', 'example', 'support'}
HEADINGS = {
    'Answers': -2.8,
    'Changes': -1.2,
    'Transcript': -1.2,
    'Examples': -1.0,
    'Summary': 0.2,
}


def predict(s, prev, line, pos, template):
    if s == ':' and prev == 'Title' and pos == 1:
        return 6.294
    if s == 'filename' and prev == '<':
        return 4.95 if pos == 1 else 3.0
    if s == '_comment' and line.endswith('<issue'):
        return -1.8
    if s in {'EMAIL', 'PASSWORD'} and line.endswith(('<', '|||')):
        return 2.9
    if s.strip() == 'protected' and re.search(r'\[email\s*$', line):
        return 1.4
    if prev.endswith('://') and s in HOSTS:
        return {'github': 1.0, 'developers': 2.2}.get(s, 1.3)
    if s == 'php' and prev.endswith('<?'):
        return -1.85 if pos <= 2 else -1.0
    if s == '··' and prev == '··':
        return 1.224

    tag = re.search(r'<(/?)([a-z]+)$', prev + s)
    if tag and tag.group(2) in TAGS:
        closing, name = bool(tag.group(1)), tag.group(2)
        value = TAGS[name][closing]
        if name == 'summary':
            if closing and '///' in line:
                value = -5.55
            elif not closing and (prev == '<' or '<details>' in line):
                value = -4.0
        if name == 'script' and not closing and template:
            value = 1.8 if s.startswith('<') else -1.0
        elif s == '<script':
            value = -2.4
        if s == '<body':
            value = -2.6
        if closing and prev.endswith('"></'):
            value *= 0.5
        if '`<' in prev:
            value *= 0.65
        return value

    word, before = s.strip(), prev.strip()
    heading = bool(re.match(r'^\s*#{1,6}(?: |$)', line))
    count_heading = bool(re.fullmatch(r'\s*#{1,6} [0-9]+', line))
    if word in FEEDBACK and before.isdecimal():
        if count_heading:
            return -4.0 if word == 'Answers' else -4.6
        if word == 'Comments' and line.strip().isdecimal():
            return -3.5
        return -3.3 if word == 'Responses' else -1.5
    if word in {'comments', 'reviews'} and before.isdecimal():
        return -1.4
    if not line.strip() and word in {'Comments', 'Answers', 'Examples'}:
        return {'Comments': -2.7, 'Answers': -1.2, 'Examples': -1.0}[word]
    related = re.search(r'(Related|Similar) ([A-Za-z]+)$', line + s)
    if s.strip() and related and related.group(2).lower() in RELATED:
        label = related.group(2).lower()
        if related.group(1) == 'Related' and label == 'questions':
            return -5.5 if heading else -4.7
        if heading and label in {'topics', 'documents'}:
            return -3.6 if label == 'topics' else -2.4
        return -1.4
    if word == 'Questions' and before in {'Asked', 'asked'}:
        return -0.8
    if word.lower() == 'summary' and before in {'Solution', 'Resource'}:
        return -1.6
    if re.fullmatch(r'\s*#{1,6}', line) and word in HEADINGS:
        return HEADINGS[word]
    if '\n' in s and s.isspace() and heading:
        if re.search(r'Related [Qq]uestions$', line):
            return -1.9
        if re.search(r'\b(?:FAQs|Posts|Recent|Stories)$', line):
            return -1.6
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, line, pos, template = '', '', 0, False
    else:
        _, prev, line, pos, template = carry
    s = prefix.token_strings[-1]
    template = template or bool(re.search(r'</?template$', prev + s))
    value = predict(s, prev, line, pos, template)
    text = line + s.replace('\\n', '\n').replace('\\r', '\r')
    line = re.split(r'[\r\n]', text)[-1][-160:]
    return (doc, s, line, pos + 1, template), float(value)

"""Sparse spelling and phrase rules for liquid-consonant syllables.

The largest rules distinguish r-al from g-al, especially when a tokenizer
splits the syllable. Accents and Cyrillic spellings are transliterated for
this comparison. Whole words containing 'ral' get a much smaller, rarity-
weighted response. Separate rules cover let-me/let's, Japanese ra-ru,
French -raux, and repeated middle dots. Everything else is left at zero.
These are approximations: lexicalized words and individual stems vary.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
VOWELS = 'aeiouy'


@lru_cache(maxsize=65536)
def response(previous, token):
    p, s = previous.lower(), token.lower()
    if p.strip() == 'let':
        if s == ' me':
            return 0.63
        if s == "'s":
            return 0.29
    if len(s) >= 2 and set(s) == {'·'}:
        return 1.0
    if p.endswith('ラ'):
        if s == 'ル':
            return -7.5
        if s == 'リ':
            return -2.5

    cyrillic = any('CYRILLIC' in unicodedata.name(c, '')
                   for c in s)
    s, p = anyascii(s).lower(), anyascii(p).lower()
    if not s:
        return 0.0
    fragment = not token[0].isspace()
    if fragment:
        if s.startswith('al'):
            if p.endswith('r'):
                after_vowel = len(p) > 1 and p[-2] in VOWELS
                if cyrillic:
                    return -4.0 if after_vowel else -2.0
                if s.startswith('all'):
                    return -2.5
                if s == 'al':
                    return -4.2
                return -4.0 if after_vowel else -1.5
            if p.endswith('g'):
                if s == 'al':
                    if p.strip(' -_/') == 'g':
                        return 5.5
                    return 2.0 if cyrillic else 2.8
                return 0.2 if cyrillic else 0.6
            if p.endswith(('c', 'k')):
                return 0.8 if cyrillic else 0.25
        if s.startswith('l') and p.endswith('ra'):
            return -2.2
        # French -al has the plural -aux: general / generaux.
        if s == 'ux' and p.endswith('ra'):
            return -5.5
        if re.match(r'[aeiouy]?ral', s):
            return -4.7 if s.startswith('e') else -2.4

    if re.fullmatch(r'[aeiou]?gall?', s.strip()):
        return 1.6
    if re.fullmatch(r'call?', s.strip()):
        return 0.06
    if 'ral' in s and s.strip().isalpha():
        rarity = max(0.0, 5.0 - zipf_frequency(s.strip(), 'en'))
        return -min(0.9, 0.45 * rarity)
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), response(previous, token)

"""Sparse surface approximation: document openings and lexical completions.

Most positions are near zero. Opening letters/numbers/capitalized words
have negative baselines; the opening Title: colon is strongly negative.
The remaining rules recognize dotted filler, code identifiers, and a few
CJK compound endings. They approximate selected responses, not all words.
"""
READS = ()


def initial_value(token):
    word = token.strip()
    if token.startswith('<|'):
        return -0.29
    if not word or not word.isascii():
        return 0.0
    if len(word) == 1 and word.isalpha():
        return -0.35
    if word.isdigit():
        return -0.23
    if word.isalpha() and word.istitle():
        return -0.24
    if word.islower() and word.isalpha() and token[0].isspace():
        return -0.21
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        count, previous, tail = 0, '', b''
    else:
        _, count, previous, tail = carry
    token = prefix.token_strings[-1]
    before = tail.decode('utf-8', errors='ignore')
    value = initial_value(token) if count == 0 else 0.001
    if count == 1 and previous == 'Title' and token == ':':
        value = -3.25
    elif len(token) >= 2 and set(token) == {'·'}:
        value = 0.88
    elif token.strip() == 'TreeNode':
        value = 0.5
    elif (token == 'dir'
          and previous.strip().endswith(('root', 'tmp', 'temp'))):
        value = 0.7
    elif (token == 'node'
          and previous.strip().endswith(('new', 'temp', 'count', 'link'))):
        value = 0.65
    elif (token in {'载', '載'}
          and before.endswith(('挂', '搭', '轉', '转'))):
        value = -2.5  # Mounting, carrying equipment, or reposting text.
    elif token in {'载', '載'} and before.endswith(('記', '记', '兼')):
        value = -0.7  # Recording or carrying alongside.
    elif (token in {'链接', '鏈接'}
          and before.endswith(('复制', '複製'))):
        value = -3.5  # The Copy link action.
    elif token in {'儲', '储'} and before.endswith(('聯', '联')):
        # Final character of the Chinese Federal Reserve abbreviation.
        value = 4.0
    elif token == '絡' and before.endswith('連'):
        value = -3.8  # Japanese contact/communication, 連絡.
    elif token == '락' and before.endswith('연'):
        value = -1.8  # Korean contact/communication, 연락.
    elif token == '결' and before.endswith('연'):
        value = 2.2  # Korean connection, 연결.
    elif token == 'ね' and before.endswith('重'):
        value = 1.5  # Japanese 重ね, stacking/repeating.
    tail = (tail + prefix.token_bytes[-1])[-24:]
    return (doc, count + 1, token, tail), value

"""Approximate prominent number-prefix, padding, and label responses.

Negative at the second digit of 19/20 and 30/31, adjusted by date,
arithmetic, and source-code cues. Even-width space padding is negative
at line breaks; long padding is weaker. First-label punctuation, initial
letters' periods, and GitHub's .com suffix are positive. Compatibility
digits are normalized; Chinese 一九 gets a negative year-prefix signal.
Unmatched text receives zero rather than a word-by-word lookup.
"""
import calendar
import math
import re
import unicodedata

READS = ()
MONTHS = {m.lower() for m in calendar.month_name[1:]}
MONTHS |= {m.lower() for m in calendar.month_abbr[1:]}
DATE_CUES = {
    'in', 'since', 'during', 'born', 'died', 'until',
    'before', 'after', 'the', 'year',
}
NUMBERED = re.compile(r'(?:^|\n) *\d+\t')
MATH = re.compile(r'\\(?:frac|sqrt|sum)|[=+]|\d\s*[-*^]\s*\d')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', '')
    _, previous, digits, before, tail = carry
    s = prefix.token_strings[-1]
    digit = unicodedata.normalize('NFKC', s)
    value = 0.0
    numbered = bool(NUMBERED.search(tail))

    if digit in ('0', '1', '9') and digits:
        words = re.findall(r'[A-Za-z]+', before[-32:])
        word = words[-1].lower() if words else ''
        month = word in MONTHS
        date = word in DATE_CUES
        if digit == '0' and digits[-1] == '3':
            value = -1.35 if len(digits) == 1 else -0.5
            if len(digits) == 1 and (month or before.endswith(':')):
                value = -1.9
        elif digit == '1' and digits[-1] == '3':
            value = -0.8 if len(digits) == 1 else -0.25
            if len(digits) == 1 and month:
                value = -1.4
        elif (digit, digits) in (('0', '2'), ('9', '1')):
            value = -0.55 if digit == '0' else -0.8
            line = before.rsplit('\n', 1)[-1]
            if not line.strip():
                value = -0.3
            elif date:
                value = -1.0
            elif month:
                value = -0.75 if digit == '0' else -0.95
            elif before.endswith('('):
                value = -0.75 if digit == '0' else -0.9
            elif before.endswith(('-', '.', ',', ':')):
                value = -0.2
            elif before.endswith(('=', '$')):
                value = 0.05
            if (numbered or MATH.search(tail)) and not date and not month:
                value = 0.0
        elif digit == '0' and digits[-1] == '2':
            value = 0.23
        elif digit == '9' and digits[-1] == '1':
            value = 0.1

    if s and not s.strip(' \t'):
        n = s.count(' ')
        tabs = s.count('\t')
        if n >= 2 and n % 2 == 0:
            value = -0.07
            if previous.endswith('\n'):
                value = -1.2 * math.exp(-max(0, n - 4) / 12)
                if numbered and n <= 4:
                    value = -1.3
            if tabs:
                value = -0.85 / math.sqrt(tabs)
    if s in ('.', '.)', ':', ')'):
        label = before.replace('\\n', '\n').rsplit('\n', 1)[-1].strip()
        if digits == '1' and (not label or label.endswith('(')):
            if not MATH.search(tail):
                value = 0.95
        elif s == '.' and previous.strip() in ('a', 'A', 'i', 'I'):
            value = 0.65
    if s == '.com' and tail.lower().endswith('github'):
        value = 1.1
    if s == '九' and tail.endswith('一'):
        value = -2.2

    if digit.isascii() and digit.isdigit():
        if not digits:
            before = tail
        digits = (digits + digit)[-24:]
    else:
        digits = ''
    return (doc, s, digits, before, (tail + s)[-256:]), value

programs.haiku:
"""Layer 1, MLP down-projection, component 521: a mostly silent detector that is
mostly negative. It fires on three things in running text, and is near 0 elsewhere.

1. Indentation at the start of a line. A whitespace-only token of an even number
   of spaces (2, 4, 6, ...) right after a newline is negative: about -1.1 for 2 or
   4 spaces, about -0.8 for longer even runs. Odd runs (3, 5, 7 spaces) stay near 0.
2. The second digit of a number that begins "19", "20", "30" or "31" when the
   number stands on its own (after a space, "(", ":" or a line break), e.g. the
   "9" of 1958, the "0" of 2023 or "March 30". The "0" of "30" is the strongest
   (-1.2), then "19" (-0.85), "31" (-0.8), "20" (-0.6). Decimals such as "2.20"
   do not count.
3. Positive: the "." or ")" right after a list opener "1" that stands alone (a
   numbered list such as "1." on its own line, or "(1)"), about +0.6.
4. Positive: a ".com" token (+0.3) and a run of middle-dot filler "··" (+0.85).

Everything else predicts 0. The rules read only the newest token and the one or
two before it, and reset at a document boundary.
"""

READS = ()

YEAR_VALUE = {"30": -1.2, "19": -0.85, "31": -0.8, "20": -0.6}


def _is_digit(s):
    return len(s) == 1 and s.isdigit()


def _starts_alone(s):
    # text before a number that makes it a standalone number, not a decimal or part of a word
    return s == "" or s.endswith((" ", "(", ":", "\n"))


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    docs = prefix.document_ids
    t = strings[-1]
    same_doc = len(strings) >= 2 and docs[-2] == docs[-1]
    prev = strings[-2] if same_doc else ""
    prev2 = strings[-3] if len(strings) >= 3 and same_doc and docs[-3] == docs[-1] else ""
    value = 0.0
    if t and set(t) == {" "} and prev.endswith("\n"):
        if len(t) % 2 == 0:
            value = -1.1 if len(t) <= 4 else -0.8
    elif _is_digit(t) and _is_digit(prev) and _starts_alone(prev2):
        value = YEAR_VALUE.get(prev + t, 0.0)
    elif t in (".", ")") and prev == "1" and _starts_alone(prev2):
        value = 0.6
    elif t == ".com":
        value = 0.3
    elif t == "··":
        value = 0.85
    return carry, float(value)

programs.sol:
"""A local enumeration signal, not a general repetition detector.

Commas, bullets, and repeated item openings provide evidence for a list.
Articles and conjunctions are stronger at the start of another item.
Correlative phrases provide weaker additional evidence. Keep 64 recent tokens
and reset at document boundaries; ordinary content tokens predict zero.
The constants are rough conditional activation levels, not probabilities.
"""
import re

READS = ()
ARTICLES = {'a', 'an', 'the'}
COORD = {'and', 'or', 'nor', 'but', 'y', 'e', 'et', 'und', 'oder', 'и', 'или', 'و'}
PREP = {'to', 'for', 'with', 'from', 'between', 'in', 'on', 'of', 'as'}
ADDITIVE = {'also', 'too', 'furthermore', 'moreover', 'additionally', 'plus',
            'sowie', 'также', 'oraz', '也', 'や'}
BULLETS = set('-*•▪●✓')
COMMAS = ',，、'
QUOTES = '\'"“”‘’`'
INTRO = re.compile(
    r'\b(?:such as|including|includes?|comprises?|consists? of|following|'
    r'namely|for example|e\.g\.|ranging from|ranging|range from)\b')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    h = carry[1] if carry and carry[0] == doc else []
    t = prefix.token_strings[-1]
    s, w = t.strip(), t.strip().lower()
    p = h[-1] if h else ''
    text = ''.join(h)
    sentence = re.split(r'[.!?。！？\n]', text)[-1].lower()
    length = len(sentence)
    intro_match = list(INTRO.finditer(sentence))
    intro = bool(intro_match)
    enumerated = intro and any(c in sentence[intro_match[-1].end():] for c in COMMAS)
    commas = [i for i, x in enumerate(h) if any(c in x for c in COMMAS)]
    gap = len(h) - commas[-1] if commas else 128
    same = [i for i, x in enumerate(h) if x == t]
    repeat_gap = len(h) - same[-1] if same else 128
    parallel = bool(same and ((same[-1] == 0 and len(h) < 64) or re.search(
        r'[,，、:;\n]\s*$', ''.join(h[max(0, same[-1] - 2):same[-1]]))))
    after_comma = any(c in p for c in COMMAS)
    after_coord = p.strip().lower() in COORD
    line_start = not text.split('\n')[-1].strip()
    value = 0.0
    if any(c in s for c in COMMAS):
        span = h[commas[-1] + 1:] if commas else h
        first = next((x.strip().lower() for x in span if x.strip()), '')
        span_text = ''.join(span)
        numeric = (sum(c.isdigit() for c in span_text)
                   > sum(c.isalpha() for c in span_text))
        if intro:
            value = 0.82 + 1.35 * (enumerated and repeat_gap <= 7 and length > 60)
        elif repeat_gap <= 7:
            value = 0.42 if length <= 47 else 1.12
            value -= 0.4 * numeric
            if first in COORD:
                value = -0.04
        else:
            value = (0.15 if length <= 60 else 0.35) if gap <= 12 else 0.04
        if '、' in s:
            value = max(value, 1.5 if repeat_gap <= 7 else 0.8 if gap <= 12 else 0.1)
        if re.search(r'[)\]}].*[,，、]', s):
            value = max(value, 1.5 if repeat_gap <= 13 else 0.35)
        if '\n' in t:
            value = max(value, 0.43)
    elif s in BULLETS:
        value = 0.07
        if parallel:
            value = 0.4
            if '\n' in p:
                value = 0.8 + 0.8 * (repeat_gap <= 34)
                if p.isspace():
                    value = 1.1 + (1.8 if s in '-*' else 0.65) * (repeat_gap <= 18)
    elif s in ARTICLES:
        value = 0.02
        if after_coord:
            value = 0.34 if length <= 56 else 0.63
            value += 0.6 * parallel + 0.7 * intro
        elif after_comma:
            value = 0.08 if length <= 81 else 0.33
            value += 0.5 * parallel + 1.1 * intro
    elif w in COORD:
        value = -0.04 if length <= 50 else 0.12
        if after_comma:
            value = 0.16 if length <= 73 else 0.42
            value += 0.6 * intro
        else:
            value += 0.1 * (w == 'or') + 0.2 * intro
            value += 0.3 * bool(re.search(r'\b(?:both|either|neither)\b', sentence))
    elif w in PREP:
        value = -0.01
        if w == 'to' and re.search(r'\bfrom\b', sentence):
            value = 1.2 if length <= 52 else 0.5 if length <= 154 else 0.2
        elif after_comma or after_coord:
            value = 0.35 if repeat_gap <= 12 else 0.03
    elif w in ADDITIVE:
        value = 1.8 if after_coord else 0.35
        if re.search(r'\bnot (?:only|just|merely)\b', sentence):
            value = 1.2
    elif s.isdecimal():
        value = 0.02
        if p.isspace() and gap <= 3:
            value = 0.4
        elif line_start:
            value = 0.2
    elif t.isspace() and '\n' not in t:
        value = 0.38 if after_coord else 0.18 if after_comma else 0.01
        value += 0.45 * (after_comma and parallel and repeat_gap <= 12)
    elif s and not any(c.isalnum() for c in s):
        if after_comma:
            value = 0.14 + 0.48 * (repeat_gap <= 12)
            value += 0.75 * (repeat_gap <= 12 and any(c in p for c in QUOTES))
        elif s == ';':
            value = 0.6 if length > 90 or commas else 0.04
        elif after_coord and repeat_gap <= 14:
            value = 1.2 if any(c in s for c in QUOTES) else 0.15
        elif repeat_gap <= 14 and any(c in s for c in ')]}'):
            value = 0.1
    h.append(t)
    return (doc, h[-64:]), float(value)

"""Approximate a document-opening response, not a running number counter.

The opening token (and exact repetitions of it) receives a lexical response.
Digits and number words are particularly strong, as are some punctuation and
source-code declarations. Other words use broad casing and spacing classes.
After a different token arrives the prediction is zero: this intentionally
omits the component's smaller, context-dependent fluctuations.
"""
import inflect

READS = ()
DIGITS = (6.89, 2.75, 5.50, 6.55, 5.09,
          4.97, 6.62, 5.13, 4.77, 0.21)
NUMBER_WORDS = {
    inflect.engine().number_to_words(n): n for n in range(11)
}
PREPOSITIONS = frozenset('''
    of in on at by to for from with into over after before between through
    under without within during about
'''.split())
DECLARATIONS = frozenset('''
    class def function var let const public private protected void int
    float double bool static struct enum
'''.split())
IMPORTS = frozenset('import using from use require'.split())
QUANTITIES = frozenset('many some several few both'.split())


def opening_value(text):
    word = text.strip()
    lower = word.lower()
    capital = bool(word) and word[0].isupper()
    spaced = text.startswith(' ')
    if len(text) == 1 and '0' <= text <= '9':
        return DIGITS[int(text)]
    number = NUMBER_WORDS.get(lower)
    if number is not None and number >= 2:
        if number == 10:
            return 6.0 if capital else 1.0
        value = DIGITS[number] if number < 9 else 1.8
        return value * (2.2 if capital else 1.0)
    if lower in QUANTITIES:
        return 4.5 if capital else 2.5
    if text == '<|endoftext|>':
        return 6.3
    if text.startswith('<|'):
        return -1.2
    if lower in ('package', 'namespace'):
        return 3.7 if not spaced else 0.7
    if lower in IMPORTS and not capital:
        return 1.8 if not spaced else 0.2
    if lower in DECLARATIONS and not capital:
        return 1.8 if not spaced else 0.8
    if lower == 'of':
        return 3.7 if spaced else 2.0
    if lower in PREPOSITIONS:
        if capital:
            return 2.3
        if lower == 'by':
            return 1.5
        if lower == 'with':
            return 0.8
        return 0.0
    if word == ',':
        return 2.8
    if word == '.':
        if text.count('\n') > 1:
            return 0.9
        return 2.3 if '\n' in text else 1.7
    if text.startswith('#'):
        return 2.4 if text == '##' else 1.8
    if text.startswith('/*'):
        return 2.6
    if len(text) == 2 and text[0] == '\\' and text[1] in 'nt"\\':
        return 4.0
    if text == '{':
        return 3.8
    if text == ';':
        return 1.6
    if text == ' ':
        return 0.6
    if not word:
        return 0.5 if '\n' in text else 0.0
    if not any(c.isalpha() for c in text):
        return 0.4
    if spaced:
        return -0.9
    return 0.2 if capital else -0.5


def step(carry, prefix, upstream):
    # State: document, opening token, opening run still active, opening value.
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(prefix.token_strings[-1])
        carry = (doc, token, True, value)
    elif carry[2] and token != carry[1]:
        carry = (doc, carry[1], False, carry[3])
    return carry, carry[3] if carry[2] else 0.0

programs.haiku:
"""Layer-1 MLP component 526 (down_proj): a document-opener detector.

The component reads the MLP's hidden state, and it is almost silent except at the
first token of each document (or packed-row segment). There, attention can see only
the token itself, so the value is set by which token opens the text:

- numerals (digits, and the spelled-out numbers two..nine) push it strongly positive;
  quantity words (several, some, many, multiple, various, double) push it positive;
- opening punctuation and symbols (, . # ; { \\n and the like) push it moderately positive;
- lowercase words that continue a sentence (" the", " is", " was") push it negative;
- chat/special markers such as <|im_start|> push it slightly negative.

If the document so far is one token repeated (a run such as "0 0 0" or repeated middle dots), the
value stays at the document-opening value. Other tokens, mid-document, give 0.
"""

import unicodedata

READS = ()

DIGIT_VALUE = {"0": 6.9, "1": 2.7, "2": 5.5, "3": 6.5, "4": 5.1,
               "5": 5.0, "6": 6.6, "7": 5.1, "8": 4.8, "9": 0.2}
NUMBER_WORDS = {"two", "three", "four", "five", "six", "seven", "eight", "nine"}
QUANTITY_WORDS = {"several", "some", "many", "multiple", "various", "double"}


def opener_value(s):
    """How much a token, as the first token of a text, pushes the component."""
    if s in DIGIT_VALUE:
        return DIGIT_VALUE[s]
    word = s.strip().lower()
    if word in NUMBER_WORDS:
        return 12.0 if s.strip()[:1].isupper() else 5.5
    if word in QUANTITY_WORDS:
        return 5.0
    if s.startswith("<|"):
        return -1.2
    core = s.strip()
    if core == "":
        return 0.4
    if all(unicodedata.category(c)[0] in "PS" for c in core):
        return 1.2
    if s.startswith(" ") and core.isalpha() and core[0].islower():
        return -0.9
    if core.isalpha() and core[0].isupper():
        return 0.3
    return 0.0


def step(carry, prefix, upstream):
    """carry: (first token, whether the document so far repeats it), or None."""
    tok = prefix.token_strings[-1]
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        first, repeating = tok, True
    else:
        first, repeating = carry
        repeating = repeating and tok == first
    value = opener_value(first) if repeating else 0.0
    return (first, repeating), float(value)

programs.sol:
"""A spelling-specific lexical mixture, not a general topic detector.

Han paper, egg, spiral-shell and general-outline spellings are positive;
央/中央 ('central') is negative. Paper/shell compounds are weaker. English
paper/diagram is negative and central is positive. A separate rule handles
first-token character classes and comment openers. Incomplete UTF-8 characters
are joined across tokens, with state reset at document boundaries. Other rare
character responses and contextual variation are deliberately left unmodelled.
"""

import codecs

READS = ()


def lexical(text):
    s = text.strip()
    if s in ('纸', '紙'):
        return 2.6                       # paper character
    if '纸' in s or '紙' in s:
        return 0.6                       # paper-containing compound
    if s in ('蛋', '鸡蛋'):
        return 1.2                       # egg
    if s == '螺':
        return 4.4                       # spiral shell
    if '螺' in s:
        return 0.6
    if s == '中央':
        return -1.9                      # central
    if s == '央':
        return -1.0
    if s == '概':
        return 1.1                       # general outline
    if s.lower() in ('paper', 'papers', 'diagram', 'diagrams'):
        return -0.22
    if s.lower() == 'central':
        return 0.20
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    pending = b'' if first else carry[1]
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'ignore', False)
    value = lexical(text)
    if first:
        s = text.strip()
        value = -0.18
        if text == '\r':
            value = -4.4
        elif s.startswith(('/*', '//', '"""', "'''")):
            value = -1.5
        elif s.startswith('#'):
            value = -0.9
        elif not s:
            value = 0.08
        elif s.startswith('<|'):
            value = -0.33
        elif s.isdigit():
            value = -0.07
        elif s[0].isascii() and s[0].isupper():
            value = -0.26
    # Only an unfinished character survives to the next token.
    return (doc, raw[used:]), float(value)

programs.haiku:
"""Layer-1 MLP down-projection component 527: a lexical detector for a few Chinese
characters, plus a small negative kick at the first token after a document boundary.

- Paper words (纸 / 紙, "paper") give a strong positive activation (about 2.5).
- Egg (蛋 / 鸡蛋) and a handful of other single characters that begin a word (脊, 菱,
  棘, 棱, 螺, 概, 肚) give moderate positive values.
- 中央 ("centre") gives a negative value (about -1.7).
- A run of middle dots "··" gives a constant 0.87.
- The first token of a document (right after <|endoftext|>, or the first token of a
  row) gives a small negative value, about -0.3 (-0.13 at the row's first token).
Everything else is about 0.
"""

READS = ()

PAPER = {"纸": 2.5, "紙": 2.0}
EGG = {"蛋": 1.3, "鸡蛋": 1.4}
OTHER = {"脊": 3.0, "螺": 4.5, "菱": 2.1, "棘": 2.0, "棱": 1.4, "概": 1.4, "肚": 1.8}
NEGATIVE = {"中央": -1.7, "··": 0.87}
TABLE = {**PAPER, **EGG, **OTHER, **NEGATIVE}
DOC_START = -0.3
ROW_START = -0.13


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    docs = prefix.document_ids
    if len(docs) == 1:
        return carry, ROW_START
    if docs[-1] != docs[-2]:
        return carry, DOC_START
    return carry, float(TABLE.get(token, 0.0))

