"""Approximate rare, document-opening source/record-format signals.

The largest bursts mark package and namespace declarations. Import and
blockquote openers are weaker signals. Two structured record headers also
trigger: an issue-comment tag, and a forum's 'N Replies Latest reply'.
Elsewhere use a small background, with a positive first-position offset.
Other token-specific variation is not modeled.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, opening = 0, ''
    else:
        _, position, opening = carry

    value = -0.005
    if position == 0:
        value = 0.07
        if token == 'package':
            value = 2.22
        elif token == 'namespace':
            value = 2.18
        elif token in {'import', 'from', 'using'}:
            value = 0.67
        elif token.strip() == '>':
            value = 0.94
    elif position == 4 and opening == '<issue_start><' and token == 'issue':
        value = 1.12
    elif position <= 8 and token.strip() == 'reply':
        if re.fullmatch(r'\d+ Replies Latest reply', opening + token):
            value = 0.75

    if position < 8:
        opening += token
    return (doc, position + 1, opening), value

