        value = 3.8 if word[:1].isupper() else 1.5
        if lower == 'utilities' and word[:1].isupper():
            value = 2.9
        if not word[:1].isupper() and text == word:
            value = 2.8
    elif lower in {'lib', 'libs'} and text.startswith(('/', '.')):
        value = 1.8 if re.search(r'/usr(?:/local)?$', before) else 0.15
    elif lower in {'helper', 'helpers'}:
        value = 1.7 if text.startswith(('/', '.')) else 0.15
        if word[:1].isupper():
            value = 0.3
    elif lower == 'utils':
