"""A detector for particular c-word spellings and subword joins.

The large responses are usually on a continuation after c: c+ott,
c+orn and c+ow are positive; c+os, c+us, c+au and c+uz are negative.
Whole corn/cot/cow/coin/clay words have weaker positive responses.
The rules distinguish whole tokens from joined pieces, rather than
pretending every occurrence of a letter sequence has the same strength.
A few plant/material characters and doubled middle dots are also positive.
There are explicit rules for because abbreviations and Japanese ko-joins.
Most weaker lexical and contextual variation is deliberately left at zero: 
this is a partial reconstruction, not a complete account of the component.
"""
import re

READS = ()
WORD_END = re.compile(r'[^\W\d_]+$')

# Whole-token spelling families; these are much weaker than c+continuations.
WHOLE = (
    (r'clays?$', 1.9),
    (r'corns?$', 1.1),
    (r'corks?$', 1.2),
    (r'cattle$', 1.0),
    (r'cot(?:ton|tage|tages)?$', 0.6),
    (r'cows?$', 0.65),
    (r'coins?$', 0.45),
    (r'coals?$', 0.2),
    (r'cor(?:al|y|ry)$', 0.75),
    (r'cutter(?:s)?$', 1.3),
)
WHOLE = [(re.compile(pattern), value) for pattern, value in WHOLE]
# Bamboo, pottery, grass, and tea.
MATERIALS = {'竹': 3.8, '陶': 2.5, '草': 0.55, '茶': 1.3}


# Weaker completions after c, in priority order.
C_COMPLETIONS = (
    (('ox', 'aux'), -1.5),
    (('au', 'um', 'use', 'ope'), -0.7),
    (('os', 'ous', 'ough', 'uss', 'oll'), -0.55),
    (('anc', 'ant', 'ase', 'ass'), -0.5),
    (('oin',), 2.2),
    (('ust',), 0.8),
    (('us',), -0.7),
    (('ot', 'ole', 'ock', 'ash', 'lay'), 1.2),
    (('ay', 'uy', 'ore', 'ors', 'ory'), 0.85),
    (('odi', 'oid', 'row'), 0.5),
)


def after_c(previous, token):
    """Spelling completions, strongest for cot(t), corn, cow and cuz."""
    if token in ('ott', 'otta'):
        return 2.1 if previous.endswith('sc') else 6.0
    if token in ('orn', 'orns'):
        return 4.5 if previous == 'c' else 2.8
    if token in ('ow', 'ows'):
        return 3.0
    if token.startswith('orne'):
        return 1.0
    if token == 'uz':
        return -3.7
    if token == 'an':
        return -0.5
    for endings, value in C_COMPLETIONS:
        if token.startswith(endings):
            return value
    return 0.0


def response(previous, token, previous_token):
    s = token.lower()
    p = previous.lower()
    if token in MATERIALS:
        return MATERIALS[token]
    if token == '··' and previous_token == '··':
        return 0.4
    # Because abbreviations and apostrophe forms are especially negative.
    if token == '/c' and previous_token.strip() == 'b':
        return -3.4
    if s.strip() in ('cause', 'cos', 'cuz'):
        if previous_token.rstrip().endswith(("'", '’', '‘')):
            return -4.0
        if s.strip() == 'cause':
            return -0.35
