    if (previous_token.endswith(('コ', 'ｺ'))
            and token.startswith(('ー', 'ッ', 'ｰ', 'ｯ'))):
        return 2.3
    attached = bool(s and s[0].isalpha())
    if attached and p.endswith('c'):
        return after_c(p, s)
    if attached:
        if p.endswith('beca') and s == 'use':
            return -4.8
        if p.endswith('ca') and s.startswith('us'):
            return -1.2
        if p.endswith('co') and s.startswith('zy'):
            return -2.2
        if p.endswith('co') and s.startswith(('les', 'lette')):
            return 0.65
        if p.endswith('cos') and s.startswith(('as', 'se')):
            return -0.7
        if p.endswith('cour') and s.startswith('ty'):
            return 2.1
        if p.endswith('col') and s.startswith('tes'):
            return 1.8
        if p.endswith('can') and s.startswith('ning'):
            return 2.8
        if p.endswith('cor') and s.startswith(('al', 'ning', 'ne', 'ry')):
            return 1.1
        if p.endswith('cut') and s.startswith(('ta', 'ter')):
            return 2.0
        if p.endswith('cur') and s in ('ly', 'ley'):
            return 1.8
        if p.endswith('cl') and s in ('ay', 'ays'):
            return 2.0
        if p.endswith('t') and s == 'te':
            return 0.65
    for pattern, value in WHOLE:
        if pattern.fullmatch(s.strip()):
            return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_token = '', ''
    else:
        _, previous, previous_token = carry
    token = prefix.token_strings[-1]
    value = response(previous, token, previous_token)
    match = WORD_END.search(previous + token)
    word = match[0][-32:] if match else ''
    return (doc, word, token), float(value)

"""A sparse approximation to several Chinese lexical responses.

Bird/island and burning characters are strongly positive, as are assurance
and social-insurance terms. Industrial development is moderately positive;
traditional culture and supervision are negative. Purpose and medical
modifiers strengthen assurance. Unmodelled lexical effects stay near zero.
An initial decorative run of middle dots or carets is handled separately.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    tail, separator = (b'', '') if start else carry[1:]
    before = tail.decode('utf-8', errors='ignore')
    raw = prefix.token_bytes[-1]
    word = prefix.token_strings[-1].strip()
    joined = (tail + raw).decode('utf-8', errors='replace')
    # Recover a character completed by this byte-level token.
    if '\ufffd' in word and joined and joined[-1] != '\ufffd':
        word = joined[-1]

    if start:
        if len(word) >= 2 and set(word) == {'·'}:
            separator = '·'
        elif len(word) >= 4 and set(word) == {'^'}:
            separator = '^'
    elif not word or set(word) != {separator}:
        separator = ''

    value = 0.15 if start else -0.002
    if separator == '·' and len(word) >= 2:
        value = 2.62
    elif separator == '^' and len(word) >= 4:
        value = 2.46
    elif word in {'鸟', '鳥', '岛', '島'}:
        value = 3.2
    elif word in {'烧', '燒'}:
        value = 2.2
    elif word == '焼':
        value = 0.6
    elif word in {'保证', '保證', '确保', '確保', '保障', '担保', '擔保'}:
        value = 1.35
        if before.endswith(('医疗', '醫療', '门诊', '門診', '综合', '綜合')):
            value = 2.5
        elif before.endswith(('以', '为', '為')):
            value = 1.8
        elif before.endswith(('可以', '完全', '有', '法治')):
            value = 0.2
    elif word in {'医保', '醫保', '社保', '参保', '參保', '社会保障'}:
        value = 1.95
    elif word in {'保险', '保險', '养老保险', '養老保險'}:
        value = 0.9
        if before.endswith(('护理', '護理', '防贫', '防貧')):
            value = 2.1
        elif before.endswith(('被', '财产', '財產')):
            value = 0.05
    elif word == '保':
        value = 0.45
    elif word in {'产业', '產業', '产业发展', '產業發展', '就业', '就業'}:
        value = 1.05
    elif word in {'传统文化', '傳統文化', '文化创意', '文化創意'}:
        value = -2.0
    elif word in {'传统', '傳統', '经验', '經驗'}:
        value = -0.55
    elif word in {'指导', '指導'}:
        value = -0.75
    elif word in {'督导', '督導'}:
        value = -1.8
    return (doc, (tail + raw)[-128:], separator), value

