"""A partial, typographic approximation of this component.

In Chinese surroundings, semicolons, questions, exclamations, parentheses and
isolated Latin capitals usually have negative responses. Repeated dots and
repeated question marks have positive responses. Kana history distinguishes
Japanese punctuation, which has weaker question/exclamation responses.
A 32-token script history resets at document boundaries. A few broad rules
also describe document starts and ordinary Western/code punctuation; individual
word-specific responses are not modeled.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
DECLARATIONS = {
    'import', 'package', 'class', 'const', 'let', 'var', 'def',
    '#include', '#pragma', '#!/',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    history = () if first else carry[1]
    text = prefix.token_strings[-1]
    word = text.strip()
    han_count = sum(pair[0] for pair in history)
    japanese = any(pair[1] for pair in history)
    previous_han = bool(history and history[-1][0])
    new = (bool(HAN.search(text)), bool(KANA.search(text)))
    carry = (doc, (history + (new,))[-32:])
    if first:
        value = 0.0
        if word in DECLARATIONS:
            value = 0.65
        elif text == '<|im_start|>':
            value = 0.47
        elif word.startswith('_') and any(c.isalpha() for c in word):
            value = 0.65
        elif (text == word and word.isascii() and word.isalpha()
              and word.istitle() and len(word) > 1):
            value = -0.3
        return carry, value

    value = 0.0
    if han_count or japanese:
        mark = word.rstrip('”’"」』')
        line_end = '\n' in text
        density = min(1.0, han_count / max(1, min(20, len(history))))
        if mark == '；':
            value = -1.0 * max(0.4, density)
        elif mark == ';':
            value = -0.9 if previous_han and not japanese else 0.0
        elif mark in ('？', '！', '?', '!'):
            if mark in ('？', '！'):
                value = -0.65 if mark == '？' else -0.45
            else:
                value = -0.3 if mark == '?' else -0.2
            value *= density if not japanese else 0.2
        elif mark in (')', '）'):
            value = -0.4 if mark == '）' else -0.45 * density
            if japanese and mark == ')':
                value = -0.18
            if line_end:
                value = 0.03
        elif mark in ('(', '（', '。（'):
            value = -0.28 * max(0.25, density)
        elif mark and set(mark) <= {'.', '…'} and (len(mark) > 1 or mark == '…'):
            value = 0.45 if '…' in mark else 0.85
            if line_end:
                value *= 0.45
        elif len(mark) >= 2 and set(mark) == {'?'}:
            value = 0.6
        elif len(mark) >= 2 and set(mark) == {'!'}:
            value = 0.2
        elif len(mark) >= 2 and set(mark) == {'・'}:
            value = 1.1
        elif mark == '||':
            value = 0.5
        elif mark == '※':
            value = 0.25 if japanese else 0.6
        elif len(text) == 1 and text.isascii() and text.isupper():
            value = -0.5 * (max(0.5, density) if japanese else density)
        elif mark == '。':
            value = -0.035
        elif mark == '、':
            value = 0.02
        if line_end and value < 0:
            value *= 0.35
    else:
        if word in ('==', '===', '====', '!='):
            value = -0.13
        elif text == '||':
            value = -0.09
        elif text == ')':
            value = 0.025
        elif text == ' .':
            value = -0.06
        elif text == '.':
            value = -0.005
        elif text == ',':
            value = -0.002
    return carry, value

"""Surface cues for relative and conditional clauses, rather than questions.

The strongest responses are to 'when', 'if', 'which', 'who' and 'where'.
Case, the preceding word, and code indentation distinguish several uses.
Some other clause markers, including translations, have weaker responses.
A small negative response also marks self-directed deliberation ('let me
think/check/try'). A document-start baseline handles the absence of context.
Unrecognized later tokens predict zero.
This is a local-text approximation, not a syntax parser.
"""
import re
import wordnet
from functools import lru_cache

READS = ()
CLAUSES = {
    'when': 1.40, 'whenever': .70,
    'which': .94, 'who': 1.03, 'whom': .55, 'whose': .38,
    'where': .72, 'wherever': .60, 'wherein': .50,
    'if': 1.00, 'whether': .55,
    'what': .10, 'how': .11, 'why': .23, 'that': .05,
    'after': .13, 'until': .16, 'unless': .19, 'because': .09,
    'then': .08,
}
