TRANSLATIONS = {
    'если': 1.15, 'когда': 1.15, 'что': .21, 'чтобы': .30,
    'который': .35, 'которые': .42,
    'qui': .53, 'que': .12, 'che': .23,
    'si': .38, 'se': .11, 'wenn': .64,
    'quando': .88, 'cuando': .90,
    '如果': .53, '当': .29,
}
QUESTION_VERBS = set('''know ask wonder determine see check understand decide
explain tell learn remember discover consider find identify specify predict
indicate show discuss analyze'''.split())
