            if word[:1].isupper():
                value = {'when': .96, 'if': .81, 'which': .40,
                         'where': .30, 'who': -.08,
                         'whether': .36, 'that': 0.0}.get(lower, value)
            if lower == 'if':
                if word.isupper():
                    value = .22
