                if previous_bases & QUESTION_VERBS or previous in {'sure', 'unclear'}:
                    value = .20 if lower == 'when' else -1.00
                elif previous in CONJUNCTIONS:
                    value = {'when': 1.05, 'which': .55}.get(lower, .30)
                elif lower in {'which', 'whom'} and previous == 'of':
                    value = .20
                elif lower == 'which' and previous in {'to', 'at', 'on', 'after'}:
                    value = .48
                elif lower == 'where':
                    if previous in {'is', 's', 'to', 'from'} or not line.strip():
                        value = .22
                    elif previous_bases & {'case', 'situation', 'scenario'}:
                        value = 1.70
                elif lower == 'who' and previous in {'of', 'on', 'about', 'over'}:
                    value = -1.0
