    'singular_be': -0.117,
}

NOUN_BEFORE_PREDICATE = {
    'noun.artifact': -0.076,
    'noun.cognition': -0.059,
    'noun.communication': -0.085,
}

NOUN_BEFORE_OF = {
    'noun.event': 0.060,
}

@lru_cache(maxsize=65536)
def classify(token):
    word = token.strip().lower()
