        return word, (GROUPS[word],)
    if word in {"'s", '’s', "'", '’'}:
        return word, ('possessive',)
    if word in FUNCTIONS or word in DETERMINERS:
        return word, (word,)
    if not word.isascii() or not word.isalpha() or len(word) < 2:
        return word, ()
    return word, tuple(wordnet.categories(word))


def class_sum(weights, classes):
    return sum(weights.get(c, 0.) for c in classes)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, article, previous, previous_word = 30, '', (), ''
