    value = .00067 + class_sum(WORD, classes)
    value += proximity * class_sum(article_weights, classes)
    if predicate:
        value += class_sum(NOUN_BEFORE_PREDICATE, previous)
    elif word == 'of':
        value += class_sum(NOUN_BEFORE_OF, previous)

