READS = ()

COPULA = {"is", "are", "was", "were", "be", "has", "have", "had", "'s", "’s"}
MODALS = {"will", "can", "must", "should", "may", "would", "could", "shall", "might"}
VERBS = {"says", "shows", "mentions", "finished", "proposed", "described",
         "obtained", "completed", "generated", "explored", "tested", "showed"}
DETERMINERS = {"the", "a", "an", "this", "that", "these", "those", "my", "his",
               "her", "its", "our", "their", "your"}
FUNCTION = DETERMINERS | {
    "it", "he", "she", "they", "we", "you", "i", "there", "here", "which", "who",
    "what", "and", "or", "but", "not", "so", "if", "when", "as", "to", "of", "in",
    "for", "on", "with", "at", "by", "from", "then", "also", "one", "all", "some",
}
DOC_START = 0.09


def is_content_word(token):
    """A word that is not a pronoun, determiner, or function word."""
    return token.isalpha() and token.lower() not in FUNCTION


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    if len(docs) == 1 or docs[-1] != docs[-2]:
        return carry, DOC_START
    word = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip()
    prev2 = prefix.token_strings[-3].strip() if len(docs) > 2 else ""
    if word in COPULA:
        if not is_content_word(prev):
            return carry, 0.0
        if prev2.lower() in DETERMINERS:
            return carry, -0.7
        return carry, -0.2
    if is_content_word(prev):
        if word in VERBS:
            return carry, -0.5
        if word in MODALS:
            return carry, -0.2
    return carry, 0.0

