"""Recognize modern-year prefixes and decimal/hexadecimal number formats.

The main response is to 19/20 and their next (decade) digit, strengthened
by calendar language and author-date citations. A point after digits is
treated as a decimal point, except in outlines, completed years, and later
version/IP separators.
Other tokens are approximated by zero. Only a short text tail is carried.
"""
import re

READS = ()
MONTH = (
    r'(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|'
    r'jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:tember)?|'
    r'oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)'
)


def number_context(before):
    """Return the context's response to 19, to 20, and decade adjustment."""
    lower = before.lower()
    end = lower.rstrip()
    word = re.search(r'([a-z]+)\W*$', lower)
    word = word[1] if word else ''
    if re.search(r'\bet\s+al[.,]?[,]?\s*$', lower):
        return 3.2, 3.2, .2
    if re.search(r'\([A-Z][a-zA-Z&., -]{2,60},\s*$', before):
        return 2.7, 2.8, .1
    if re.search(r'\b(?:spring|summer|autumn|fall|winter)\s*$', lower):
        return 3.1, 3.2, .7
    # Chinese location/time prepositions: in, from, through.
    if re.search(r'[在于於自至]\s*$', before):
        return 3.3, 3., .25
    if word in {'over', 'under', 'about', 'approximately', 'nearly',
                'than', 'only'}:
        return .9, .35, -.3
    if (re.search(r'[0-9][.,]$', before)
            or end.endswith(('$', '£', '€', '¥', '₹', '=', '+', '*', '^'))
            or word in {'line', 'lines', 'size', 'port', 'id', 'step'}):
        return .6, .15, -.7
    month_date = MONTH + r'\.?\s*(?:[0-9]{1,2}(?:st|nd|rd|th)?[,]?\s*)?$'
    if re.search(month_date, lower):
        return 2.55, 2.05, .6
    if re.search(r'[0-9],\s+$', before):
        return 1.35, .9, -.3
    if re.search(r'(?:^|\n|\\n)[ \t]*$', before):
        return 1.15, .9, -.35
    if before and before[-1].isalpha() and before[-1].isascii():
        return 1., 1., -.4
    if end.endswith(('(', '[')):
        return 2.2, 1.45, 0.
    if word in {'in', 'since', 'during', 'until', 'before', 'after',
                'year', 'years', 'born', 'dated', 'date', 'copyright',
                'mid', 'late', 'early', 'between', 'published'}:
        return 3.2, 2.7, .4
    if word in {'from', 'to', 'of', 'the', 'by', 'on', 'at', 'for'}:
        return 2.6, 1.85, .2
    if before and not before[-1].isascii():
        return 1.65, 1.9, .15
    return 1.85, 1.38, 0.


def predict(token, text):
    match = re.search(r'[0-9]+\Z', text)
    digits = match[0] if match else ''
    before = text[:-len(digits)] if digits else text
    if len(token) == 1 and token in '0123456789':
        number = digits + token
        if number in {'19', '20'}:
            a, b, _ = number_context(before)
            return a if number == '19' else b
        if digits in {'18', '19', '20'}:
            _, _, adjustment = number_context(before)
            digit = int(token)
            if digits == '20':
                if digit <= 2:
                    base = (1.3, 2.4, 2.2)[digit]
                    return base + adjustment
                return .1 if digit == 3 else -.15
            if digits == '19':
                # Later twentieth-century decades give a larger response.
                if digit < 3:
                    adjustment *= .5
                return max(-.1, .15 + .245 * digit + adjustment)
            return max(-.1, .05 * digit + .3 * adjustment)
        if number == '18':
            return .18
        if number == '120':
            return -.8
        if digits.endswith('2') and token == '0':
            return -.45
        return 0.
    if token == '.' and digits:
        if re.search(r'[0-9]\.$', before):
            return .05
        if len(digits) == 4 and digits.startswith(('19', '20')):
            return .02
        if re.search(r'(?:^|\n|\\n)[ \t]*$', before):
            return .8 if digits == '0' else .03
        if len(digits) == 1:
            value = {'0': 1.27, '1': .95}.get(digits, .65)
        else:
            value = .5 if len(digits) == 2 else .38
        if before.rstrip().endswith(('$', '£', '€', '¥', '₹', '(', '[')):
            value += .35
        return value
    if digits == '0' and re.fullmatch(r'[xX][0-9a-fA-F]*', token):
        return 1.3 if len(token) == 1 else 1.15
    return 0.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, text)
    return (doc, (text + token)[-160:]), value

