"""Years and decimals: a digit-run detector for the start of a year (19xx / 20xx).

What it does: the component fires on the digits that build a four-digit year from
1900 to 2029 as they are typed, and on the decimal point right after a lone leading 0 or 1.
  - the 2nd digit: "9" after "1" (the 9 of "19..") or "0" after "2" (the 0 of "20..")
  - the 3rd digit (the decade): high for 197x-199x and 201x-202x, mid for 193x-196x and
    200x, and near zero for 190x-192x and 203x-209x, where the year is unlikely or the
    digits are not a year at all
  - the "." in "0.50" or "1.5" (version numbers, decimals): about 1.0; "2." or "3." less
Context: the component is strongest when the number is introduced by a date word
(in, since, from, of, the, "(", a month name) and weakest when it follows code-like
punctuation (=, -, /, :, ., –), so year values are scaled up or down by that.
Everything else predicts 0.
"""

READS = ()

DATE_CUES = {"in", "In", "since", "from", "of", "the", "(", "born", "until", "during",
             "January", "February", "March", "April", "May", "June", "July", "August",
             "September", "October", "November", "December"}
CODE_CUES = {"=", "-", "/", ":", ".", "–"}
DOT_VALUE = {"0": 1.0, "1": 1.0, "2": 0.4, "3": 0.5}


def year_digit(run, digit):
    """Activation for a digit that continues the digit run `run` (its digits so far)."""
    if run == "1":
        return 2.2 if digit == "9" else 0.0
    if run == "2":
        return 1.5 if digit == "0" else 0.0
    if run == "19":
        return 2.4 if digit in "789" else (1.5 if digit in "3456" else 0.4 if digit in "012" else 0.0)
    if run == "20":
        return 2.6 if digit in "12" else (1.5 if digit == "0" else 0.0)
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    prev_doc, run, lead, last = carry if carry is not None else (None, "", "", "")
    if doc != prev_doc:
        run, lead, last = "", "", ""
    value = 0.0
    if len(tok) == 1 and tok.isdigit():
        if run == "":
            lead = last  # the word or mark just before this number
        value = year_digit(run, tok)
        if value and lead in DATE_CUES:
            value *= 1.4
        elif value and lead in CODE_CUES:
            value *= 0.4
        run = run + tok
    else:
        if tok == "." and run in DOT_VALUE:
            value = DOT_VALUE[run]
        run = ""
    if tok.strip():
        last = tok.strip()
    return (doc, run, lead, last), value

