        return -0.25
    if root.group() == 'graf' and ending.startswith('t'):
        return 0.7 if ending == 'ting' else 0.0

    if root.end() <= old:
        # A new piece continues a root already present in the word.
        if gram:
            if ending == 'ma':
                return -5.4
            if ending in ('m', 'my'):
                return -3.4
            if ending in ('os', 'mat', 'matic', 'i', 'a', 'mu', 'me'):
                return -1.7
            return -0.3 if len(ending) > 4 else -0.1
        if ending in ('a', 'h', 'iph', 'ie', 'es'):
            return -4.8
        if ending in ('i', 'ic', 'ica', 'ico', 'ism', 'ien', 'er', 'y'):
            return -2.9
        if ending in ('ing', 'ting', 'ical'):
            return 1.0
        return -0.7 if ending == 's' else -0.15

    if root.start() < old:
        if gram:
            return -2.6
        return -9.0 if old == root.end() - 1 else -5.1

    inside = old > 0
    if gram:
        return -1.4 if inside else -0.4
    pair = GRAPH_ENDINGS.get(ending, (-0.25, 0.0))
    return pair[0 if inside else 1]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prior = carry[1] if carry is not None and carry[0] == doc else ''
    text = spelling(prefix.token_strings[-1])
    pieces = list(re.finditer('[a-z]+', text))
    if not pieces:
        return (doc, ''), 0.0
    first, last = pieces[0], pieces[-1]
    old = len(prior) if first.start() == 0 else 0
    word = prior + first.group() if old else first.group()
    value = response(word, old)
    tail = last.group() if last.end() == len(text) else ''
    if len(pieces) == 1 and first.start() == 0 and last.end() == len(text):
        tail = word
    return (doc, tail[-40:]), value

"""Recognize package/pkg spellings, especially paths and split spellings.

The strongest responses are to pkg and to pieces completing package. Some
short p + a/k/g spellings also respond. Uppercase PAS/SED fragments and
selected Greek pi-vowel boundaries have negative sign. This is a spelling heuristic, not a general
semantic test for packages; unrelated tokens return zero.
"""
import re

READS = ()
_PACKAGE = re.compile(r'packag(?:e[sd]?|ing)$')


def predict(token, previous, recent, start):
    s, p = token.lower(), previous.lower()
    if not token:
        return 0.0
    word = s.lstrip(" /._-(\t\n")
    mark = s[:len(s) - len(word)]

    if word == 'pkg':
        if mark == '(':
            return 3.8
        if mark == '_':
            return 5.6
        return 8.4
    if _PACKAGE.fullmatch(word):
        plural = word.endswith('s')
        if not mark and (start or previous == '<|endoftext|>'):
            return -1.2
        if mark == '/':
            return 9.4 if plural else 5.1
        if mark == '-':
            return 2.3 if plural else 5.0
        if mark in ('.', '_', '('):
            return 3.1
        if token.strip().isupper():
            return 5.8
        if token.lstrip()[:1].isupper():
            return 4.2
        if mark:
            return 3.8 if plural else 3.2
        if previous.endswith('/'):
            return 7.8
        if previous.rstrip().endswith(('"', "'", '`')):
            return 5.2
        return 4.3
    if word == 'pak':
        return 6.2
    if word == 'pag':
        return 3.0
    if word in ('pac', 'pk'):
        return 1.4
    if re.fullmatch(r'pakistani?', word):
        return 2.3 if word.endswith('i') else 1.0
    if re.fullmatch(r'pack(?:s|ed|ing)?', word):
        if token == 'PACK':
            return 7.5
        return 2.0 if not mark and word == 'pack' else 0.5
    if token.strip() == 'PAS':
        return -0.7
    if token == 'SED' and p.endswith('pas'):
        return -1.4

    # Join adjacent fragments of one spelling, never across whitespace.
    if token[:1].isspace():
        return 0.0
    tail = recent.lower()
    if tail.endswith('pack') and s.startswith('ag'):
        return 8.5
    if tail.endswith(('pak', 'пак')) and s.startswith(('et', 'ет')):
        return 6.0
    if tail.endswith('pk') and s.startswith('g'):
        return 11.5 if s.startswith('gs') or token == 'G' else 4.0
    if p.endswith('π') and s[:1] in 'αεάέ':
        return -3.0 if previous[:1].isspace() else -1.0
    if tail.endswith('πα') and s.startswith('ρ'):
        return -1.6
    if p.endswith(('p', 'п')):
        if s.startswith(('kg', 'кг')):
            return 15.8
        if s.startswith(('ak', 'ак')):
            return 7.8
        if s.startswith('ackag'):
            return 8.5
        if s.startswith('ack'):
            return 5.8 if len(s) <= 4 else 1.8
        if s.startswith(('ag', 'аг', 'ág')):
            return 4.5 if len(s) <= 3 else 1.2
        if s.startswith(('ac', 'ац')):
            return 2.8 if len(s) <= 4 and not p.endswith('sp') else 0.1
        if token.startswith('AS'):
            return -2.1
        if s.startswith('ā'):
            return -2.5
        if s in 'áàäâ' and len(s) == 1:
            return 3.0
        if s.startswith(('k', 'к', 'g', 'г')):
            return 1.2
    if tail.endswith('パッ') and token.startswith('ケ'):
        return 7.0
    if tail.endswith('パッケ') and token.startswith('ージ'):
        return 8.5
    if tail.endswith('パ'):
        # Japanese k/g syllables, with optional gemination mark.
        kana = token.lstrip('ッ')[:1]
        if kana and kana in 'カキクケコガギグゲゴ':
            return 5.0
        if token == 'ッ':
            return 2.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, recent = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]
    value = predict(token, previous, recent, start)
    return (doc, token, (recent + token)[-24:]), value

"""Approximate biological names and scientific-text markup.

Keep the current word and a short text tail. Recognize productive Greek/Latin
name-formers and dictionary-listed microbial taxa on continuation tokens.
Separate rules recognize citations, reference attributes, anchors, inline
scientific formatting, and document-initial Title: fields. Constants approximate
training values; individual names and contexts have different strengths.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
WORD_END = re.compile(r'[^\W\d_]+$')
LATIN_ENDINGS = set('''a ae as es is us um ium ia ella ina osa oma ema ma
    era ota ila ria lla atha phyta ata ans ens ensis ales iales oides idae
    aceae ace inae illus occus ci tes etes'''.split())

# Name-forming roots: bacteria, monads, cocci, rods, viruses, and Greek
# animal/plant descriptors (tooth, beast, leaf, wing, resemblance, etc.).
NAME_FORMERS = (
    ('bacterium', 9.0), ('bacteria', 5.7), ('bacter', 8.3),
    ('monas', 13.3), ('coccus', 7.2), ('cocci', 5.5),
    ('bacillus', 7.7), ('virus', 2.25), ('coccal', 5.0),
    ('opsis', 7.5), ('ophila', 9.7), ('odon', 1.5),
    ('therium', 5.2), ('phyllum', 5.2), ('optera', 5.2),
    ('oides', 5.2), ('myces', 5.2), ('cystis', 5.2),
    ('plasma', 5.2), ('rhabditis', 5.2),
)

@lru_cache(maxsize=100000)
def biological_word(w):
    living = bool(wordnet.categories(w) & {'noun.animal', 'noun.plant'})
    microbial = living and any(wordnet.is_a(w, kind) for kind in (
        'microorganism', 'fungus', 'bacteria genus',
        'fungus genus', 'protoctist genus'))
    return living, microbial, zipf_frequency(w, 'en')


def markup(token, prev, tail):
    if token == ':' and tail == 'Title':
        return -4.67
    if token == '-type' and prev == 'ref':
        return 13.3
    if token == '#' and prev.endswith(']('):
        return 8.3
    if token == '#' and prev in (' {', '){'):
        return 6.8
    if token in ('[@', ' [@'):
        if prev.endswith('['):
            return 9.8
        if prev.endswith('^'):
            return 7.5
        return 1.9 if token.startswith(' ') else 2.9
    if token == '@' and prev.endswith('['):
        return 8.0
    if token == '="' and prev == '-type':
        return 2.5
    if token == '{' and prev in ('begin', 'end'):
        return 1.4
    if token == '](':
        return 2.0
    if token == '~':
        if re.fullmatch(r'\s*[A-Z][a-z]?', prev):
            return 3.9
        if prev.isdigit() and '~' in tail:
            return 2.7
    if token in ('*', ' *', ' (*', '*.'):  # Inline emphasis, not a bullet.
        line = tail.rsplit('\n', 1)[-1]
        prose = len(re.findall(r' [a-z]{3,}', line)) >= 3
        if not any(c in line for c in '=;{}_$`'):
            if token.startswith(' ') and prose:
                return 1.1
            if prev.isalpha() and tail.count('*') % 2:
                return 1.1
    if token in ('^', ' ^', '^\\', '.^') and '$' not in tail:
        if not any(c in tail for c in '=;{}_`'):
            if (prev.strip().isalpha() and len(prev.strip()) >= 3 or
                    prev in ('−', '+', '~', '†') or token.endswith('\\')):
                return 3.3
    if token == ' $$':
        return -0.25
    return None


def predict(carry, token, document):
    if carry is None or carry[0] != document:
        carry = (document, '', '', '')
    _, before, prev, tail = carry
    m = WORD_END.search(before + token)
    word = m.group() if m else ''
    state = (document, word, token, (tail + token)[-80:])
    value = markup(token, prev, tail)
    if value is not None:
        return state, value

    w = word.lower()
    if token.isascii() and token.isalpha() and token.islower():
        if before and word == before + token and len(w) >= 5:
            # Bare bacter- is weaker than a composite microbial name.
            if w in ('bacter', 'bacterium'):
                return state, 2.0
            for ending, strength in NAME_FORMERS:
                if w.endswith(ending) and len(w) > len(ending):
                    return state, strength
            if token == 'omon' and w.endswith('mon'):
                return state, 1.9
            if token in LATIN_ENDINGS:
                living, microbial, freq = biological_word(w)
                if microbial and len(w) >= 7 and (len(w) >= 9 or word.istitle()):
                    return state, 6.8
                if living and len(w) >= 9 and freq < 3.5:
                    return state, 1.7
                if len(w) >= 6 and freq < 2:
                    return state, 0.25

    return state, 0.0


def step(carry, prefix, upstream):
    return predict(carry, prefix.token_strings[-1], prefix.document_ids[-1])

"""Detect detached spaces: especially the second token of a run of blanks.

Most ordinary tokens get zero. A standalone space gets a positive pulse, larger
when it extends an existing blank; a space after a line break gets very little.
The pulse is stronger near the document opening and weaker for long blank runs.
Closing a double-spaced number, or following an escaped newline, suppresses it.
Space-newline tokens and nonbreaking spaces get smaller pulses. Two document-
opening markers and the colon of an opening Title: header are special cases.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, previous, tail, double_number = 0, '', '', False
    else:
        _, age, previous, tail, double_number = carry
        age += 1
    value = 0.0
    if text == ' ':
        if age == 0:
            value = -2.08
        elif previous.endswith(('\n', '\r')):
            value = 0.12
        elif previous and previous.strip(' ') == '':
            if len(previous) == 1:
                value = 2.4
            else:
                value = 2.0 if len(previous) < 7 else 1.5
            value += 0.4 * max(0.0, 1.0 - age / 128)
        elif tail.endswith('\\n'):
            value = -0.14
        elif previous[-1:].isdigit():
            value = -0.18 if double_number else 0.70
        else:
            value = 0.70
    elif text.startswith(' ') and text.isspace() and '\n' in text:
        blanks = len(text) - len(text.lstrip(' '))
        pulse = 1.0 if '\r' in text else 0.55 if text.count('\n') > 1 else 0.76
        value = pulse / blanks
    elif text == '\xa0':
        value = 0.42
    elif age == 0 and text == '<|im_start|>':
        value = 1.72
    elif age == 0 and text == '\t':
        value = 5.70
    elif age == 1 and previous == 'Title' and text == ':':
        value = 35.39
    if text == ' ':
        double_number = bool(previous) and previous.strip(' ') == ''
    elif not text.isdigit():
        double_number = False
    return (doc, age, text, (tail + text)[-2:], double_number), value

programs.haiku:
"""A lone space token (the tokenizer's separator before a digit), read in context."""
READS = ()

MONTHS = {"January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December"}

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if cur != " ":
        if cur in (" \n", " \n\n", " \r\n", "\r", "\xa0"):
            return carry, 0.6
        return carry, 0.0
    if not same_doc:
        return carry, 0.0
    prev = prefix.token_strings[-2]
    word = prev.strip()
    if word == "":
        return carry, 1.9
    if prev.endswith("\n"):
        return carry, 0.15
    if word in MONTHS:
        return carry, 0.05
    if word.isdigit():
        return carry, 0.4
    if word[:1].isupper():
        return carry, 0.45
    return carry, 0.8

programs.sol:
"""Blank continuation lines in formatted comments, quotations and patches.

The response is strongest when a marker-only line follows a nonempty line
with the same marker. Stars in indented documentation comments dominate.
Comment openers, printed line numbers and a second newline weaken it.
Bare newline tokens are suppressed. Responses are conservatively shrunk
by 20% because these surface patterns do not fix their exact magnitude.
Ordinary text is assigned zero; rare lexical/byte-specific responses are
not modeled.
"""
import re

READS = ()


def unlist(line):
    """Remove printed line numbers or patch prefixes before comment marks."""
    return re.sub(r'^(?:\d+\s+|[+-]\s+)(?=[*/#])', '', line.strip())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', None)
    _, line, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if '\n' not in token:
        return (doc, (line + token)[:500], previous), value

    finished = line + token.split('\n', 1)[0]
    marker = unlist(finished)
    prev = unlist(previous or '')
    repeated = bool(marker) and prev.startswith(marker)
    content = prev[len(marker):].strip() if repeated else ''
    if marker == '*':
        if repeated and content:
            value = 9.5 if len(finished) - len(finished.lstrip()) > 1 else 7.5
            if content.rstrip().endswith('>'):
                value *= 0.75
        elif repeated:
            value = 6.5
        elif prev.startswith('/*'):
            value = 2.5
    elif marker in ('//', '///'):
        value = 6.5 if repeated else (6.5 if previous is None else 0.5)
        if content and not content.strip('/'):
            value = 4.0
        if '<' in content:
            value *= 0.6
    elif marker == '#':
        value = 5.2 if repeated else 0.0
    elif marker == '--':
        value = 4.7 if repeated else 0.2
    elif marker in ('+', '-'):
        value = (3.2 if content else 1.5) if repeated else 0.0
    elif marker and set(marker) <= {'>', ' '}:
        value = 3.0 if repeated else 0.0
    elif marker == '|':
        value = 1.1 if repeated else -0.1
    if re.match(r'\d+\s+', finished.strip()):
        value = (3.8 if repeated else 1.0) if marker == '*' else value * 0.45
    elif re.match(r'[+-]\s+', finished.strip()) and marker in ('//', '///'):
        value *= 0.6
    # Bare newlines do not carry the blank-line formatting signal.
    if not token.split('\n', 1)[0].strip('\r'):
        value = 0.0
    if token.count('\n') > 1:
        value *= 0.3
    return (doc, token.rsplit('\n', 1)[-1], finished[:500]), 0.8 * value

programs.haiku:
"""Newline that closes an empty comment-style line inside a block of prefixed lines.

Inside a block whose lines all start with the same marker -- a Javadoc block's ` *`, a
`///` doc comment, a `//`, `#` or `--` comment, a quoted `>` reply, a diff's `+` -- the
newline that ends a bare marker line (the marker with nothing after it) fires. The model is
in the middle of the block and expects the next line to carry the marker too. The response
is strongest for ` *` (also inside a diff's `+` lines), weaker for `#`, `///`, `//`, `--`,
and weakest for `+`, `-`, `>`, `|`; it is about half as large when the lines carry a
`cat -n` line number. A bare ` *` line right under a `/**` opener also gives a moderate
response.

The character 御 (as in 御姐) is strongly negative on its own, whatever its context.
Everything else predicts 0.
"""

import re

READS = ()

# Response of the newline after a bare marker line whose line above starts with that marker.
STRENGTH = {"*": 8.0, "#": 4.9, "///": 4.3, "//": 4.1, "--": 4.5, ">>": 4.0, ">": 2.8,
            "-": 2.8, "+": 2.1, "|": 1.0}
OPENER_STAR = 3.5  # a bare " *" line right under a "/**" opener
NEGATIVE_TOKENS = {"御": -7.1}
LINE_NUMBER = re.compile(r"^\s*\d+\t")  # the number prefix of a `cat -n` listing


def clean(line):
    """The line without its `cat -n` number and surrounding spaces."""
    return LINE_NUMBER.sub("", line).strip()


def body(line):
    """The line's text after a diff sign (`+ ` or `- `), if it has one."""
    text = clean(line)
    if text[:1] in "+-" and text[1:2] == " ":
        return text[1:].strip()
    return text


def step(carry, prefix, upstream):
    # carry: (the current line so far, the last complete line), both as text
    cur, above = carry if carry is not None else ("", "")
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        cur, above = "", ""
    token = prefix.token_strings[-1]
    value = NEGATIVE_TOKENS.get(token, 0.0)
    if "\n" in token:
        head, rest = token.split("\n", 1)
        marker = clean(cur + head)
        if marker not in STRENGTH:
            marker = body(cur + head)
        if marker in STRENGTH and rest.strip("\n") == "":
            if clean(above).startswith(marker) or body(above).startswith(marker):
                value = STRENGTH[marker]
                if LINE_NUMBER.match(cur) or LINE_NUMBER.match(above):
                    value /= 2
            elif marker == "*" and clean(above).startswith("/*"):
                value = OPENER_STAR
    parts = token.split("\n")
    if len(parts) > 1:
        above = (cur + parts[0]) if len(parts) == 2 else parts[-2]
        cur = parts[-1]
    else:
        cur = cur + token
    return (cur, above), value

"""Layer 1 MLP neuron 550 (this component's direction is almost exactly that neuron).

Almost always near zero; it spikes, with either sign, on pieces of Indonesian words split
across tokens, but those spikes depend on context in a way I could not reduce to a rule.
What is reliable is the first token of each document: there the layer sees no earlier text,
so the activation is set by that token alone, typically negative for capitalised words and
numbers and near zero for words that start with a space.

This program predicts that first-token value by character class and predicts 0 elsewhere.
"""

READS = ()


def _first_token_value(token: str) -> float:
    if token[:1].isdigit():
        return -0.2
    if token[:1].isupper():
        return -0.1
    if token.startswith(" "):
        return -0.02
    return -0.05


def step(carry, prefix, upstream):
    ids = prefix.document_ids
    starts_document = len(ids) == 1 or ids[-1] != ids[-2]
    if not starts_document:
        return None, 0.0
    return None, float(_first_token_value(prefix.token_strings[-1]))

programs.sol:
"""Approximate local action/complement responses, not a full grammatical parser.

Self-contained actions (especially crying, leaving and driving) tend negative;
several object-taking or prepositional continuations tend positive. Recent
words disambiguate some noun/verb readings. A few fixed phrases and opening
conventions have separate strengths. Unrecognized tokens predict zero.
"""
from functools import lru_cache
import wordnet

READS = ()

AUXILIARIES = set(
    'am is are was were be been being have has had do does did can could '
    'will would shall should may might must'.split())
VERB_CUES = AUXILIARIES | set(
    'i you he she it we they who someone somebody person speaker to and or '
    'while whilst when then not never only just longer'.split())
MOTION = set('go come get return arrive reach walk drive fly head move'.split())
# Root families; strengths for other use, a predicate cue, and an -ing form.
ACTIONS = (
    ('cry weep sob', -.06, -.67, -.37),
    ('scream laugh', -.19, -.36, -.25),
    ('leave arrive depart', -.19, -.30, -.18),
    ('drive walk jog', -.08, -.23, -.23),
    ('exercise', -.09, -.12, -.46),
    ('rest', -.02, -.34, -.34),
    ('sleep pee socialize', -.07, -.12, -.09),
    ('work study talk wait stand sit', 0., -.10, -.06),
    ('die retire marry', -.01, -.13, -.05),
    ('call apply', -.04, -.09, -.14),
    ('do', .01, .05, .11),
    ('purchase pursue conduct undertake appoint tell see know hear hold wield share',
     .02, .05, .06),
)
ACTIONS = tuple((set(words.split()), a, b, c) for words, a, b, c in ACTIONS)

@lru_cache(maxsize=32768)
def roots(word):
    return frozenset(wordnet.base_forms(word, 'verb')) | {word}

@lru_cache(maxsize=65536)
def response(token, previous, opening, second):
    if opening:
        if token == 'Title':
            return .75
        if token == 'Person':
            return .63
        if token in {'“', '‘'}:
            return -1.02
        if token in {'const', 'var', 'function', '#ifndef'}:
            return -.89
        if token in {'His', 'Her'}:
            return -.86
        return 0.
    if second and previous == 'Title' and token == ':':
        return 3.33
    if token == '··' and previous == token:
        return -.78
    # Chinese action phrases: crying, squatting down, gathering, contacting.
    if token == '着' and previous == '哭':
        return -1.23
    if token == '下来' and previous == '蹲':
        return -.94
    if token == '集合' and previous in {'中', '广场', '到'}:
        return -1.05
    if token == '联系' and previous in {'您', '你', '我们', '与', '我'}:
        return -.60
    word, prev = token.strip().lower(), previous.strip().lower()
    wr, pr = roots(word), roots(prev)
    if word == 'formula' and prev == 'infant':
        return -.77
    if word == 'home' and pr & MOTION:
        return -.65
    if word in {'outside', 'here', 'away'} and pr & MOTION:
        return -.29
    if word in {'rich', 'richer'} and pr & {'get', 'become', 'grow'}:
        return -.75
    if word == 'up' and pr & {'wake', 'grow'}:
        return -.39
    if word in {'in', '-in', 'ins'} and pr & {'log', 'sign', 'check'}:
        return -.45
    if (word == 'bed' and prev == 'in') or (word == 'rest' and prev == 'at'):
        return -.45
    if word in {'late', 'alone'} and pr & {'be', 'stay', 'get'}:
        return -.45
    if word == 'across' and pr & {'come', 'stumble'}:
        return .65 if prev == 'came' else .32
    if word == 'into' and pr & MOTION:
        return .40 if prev == 'went' else .18
    if word in {'on', 'through', 'over', 'upon', 'past', 'to'} and pr & MOTION:
        return .09
    if word == 'with' and 'work' in pr:
        return .17
    if word == 'rid' and 'get' in pr:
        return .34
    if word in {'lucky', 'fortunate', 'unlucky'}:
        return .42 if pr & {'be', 'get'} or prev in {'’m', '’re'} else .25
