"""Layer-1 MLP down_proj component 551: a sparse, mostly lexical feature.

What it does, in plain terms:
1. First token of each document (the model resets attention there, so the token
   stands alone): usually negative, most negative for whitespace and punctuation.
2. The colon in a "Title:" header that opens a document: a large positive spike.
3. A run of the double middle-dot filler token "··": strongly negative.
4. Mid-document words about a person leaving, arriving, moving, staying, resting or
   waiting (leave, arrive, walk, drive, stay, sit, stand, rest, wait, stop, home, away):
   mildly negative.
5. Mid-document words for doing/telling and object pronouns (do, doing, told, him,
   her, who, whom) and every/across/born: mildly positive.
Everything else predicts 0.
"""
READS = ()

MOVE_REST = {
    "leave", "leaves", "leaving", "arrive", "arrived", "arrives", "arriving",
    "walk", "walks", "walking", "walked", "drive", "driving", "drove", "driven",
    "stay", "stays", "stayed", "staying", "sit", "sat", "sitting", "stand", "standing",
    "stood", "rest", "resting", "wait", "waiting", "stop", "stopping", "home", "away",
    "gone", "alone", "bed", "outside", "departure",
}
TALK_CRY = {"cry", "cries", "crying", "cried", "talk", "talking", "talks", "meet", "meeting",
            "exercise", "exercising", "apply", "applying", "call", "calling", "play", "playing"}
DO_TELL = {"do", "doing", "told", "every", "across", "born", "him", "her", "who", "whom"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    t = prefix.position
    doc_start = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if doc_start:
        if s.startswith("<|"):
            return None, 0.2
        if s.strip() == "" or not any(c.isalnum() for c in s):
            return None, -0.3
        return None, -0.15
    if s == ":" and prefix.token_strings[-2].strip() == "Title":
        if t == 1 or prefix.document_ids[-2] != prefix.document_ids[-3]:
            return None, 3.33
    if s == "··":
        return None, -0.78
    if s.startswith(" "):
        w = s[1:]
        if w in MOVE_REST or w in TALK_CRY:
            return None, -0.15
        if w in DO_TELL:
            return None, 0.08
    return None, 0.0

