"""A sparse approximation using document boundaries and typography.

Predict positive starts for articles, the pronoun I, decimal digits,
code declarations and test labels. Leading repetitions retain that start
response. Leading middle-dot runs and caret underlines have their own response.
In running text, six has a small negative bias. A spaced ampersand is
positive in French with old spellings, including long s transcribed as f.
Most ordinary tokens stay near zero. This misses many isolated OCR spikes
and deliberately does not memorize word-specific residual activations.
"""
import re

READS = ()
FRENCH_FUNCTION_WORD = re.compile(
    r"\b(?:le|les|des|du|une|qui|que|il|au|pour|avec|dans|nous|vous)\b",
    re.IGNORECASE,
)
OLD_FRENCH = re.compile(
    r"\b(?:eft|fes|fon|fe|auffi|étoit|avoit|faifoit)\b", re.IGNORECASE
)


