    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    history = "" if initial else carry[1]
    leading = initial or (carry[2] and text == carry[3])
    value = 0.002

    if leading:
        if text and set(text) == {'·'} and len(text) >= 2:
            value = 0.76
        elif text and set(text) == {'^'} and len(text) >= 4:
            value = 1.0
        elif text == '\x00':
            value = 2.21
        elif text == '\r':
            value = -3.83
        elif text == 'def':
            value = 2.13
        elif text == 'class':
            value = 0.82
        elif text == 'package':
            value = 0.44
        elif text in {'test', 'tests'}:
            value = 1.2
        elif text in {'The', 'A', 'An', 'I'}:
            value = 0.43
        elif len(text) == 1 and text in '0123456789':
            value = 0.28
        elif text.isspace():
            value = 0.16
    elif text == '6':
        previous = history[-1:]
        if previous.isalpha():
            value = -0.094
        elif previous.isspace():
            value = -0.073
        elif previous.isdigit():
            value = -0.031
        else:
            value = -0.045
    elif text == ' &':
        french = len(FRENCH_FUNCTION_WORD.findall(history)) >= 2
        old_spelling = 'ſ' in history or OLD_FRENCH.search(history)
        if french and old_spelling:
            value = 0.50

    return (doc, (history + text)[-512:], leading, text), value

"""Approximate a formatting-boundary signal, rather than ordinary word content.

A lone blank starting indentation (also inside a string) is positive; one
following a longer whitespace token is usually negative. English month-name
date parts are positive. Tabs, nonbreaking spaces and boolean operators have
separate rules. Ordinary text is left at zero, deliberately omitting lexical
idiosyncrasies. The bounded text carry resets at document boundaries.
"""
import calendar
import re

READS = ()
MONTH_NAMES = calendar.month_name[1:] + calendar.month_abbr[1:]
MONTH_SET = frozenset(m.casefold() for m in MONTH_NAMES)
MONTHS = '|'.join(MONTH_NAMES)
DAY = r'\d{1,2}(?:st|nd|rd|th)?'
DAY_NUMBER = re.compile(rf'\b{DAY}$', re.I)
DAY_END = re.compile(rf'\b(?:{MONTHS})\.? +{DAY}$', re.I)
YEAR_BOUNDARY = re.compile(
    rf'(?:\b(?:{MONTHS})\.? +{DAY},|\b{DAY} +(?:{MONTHS})\.?)$',
    re.I)
# A quote opened after an operator, argument delimiter, or output keyword.
STRING_START = re.compile(
    r'''(?:[=(,:+]|<<|\becho)\s*[rubf]{0,2}\\*["']$''', re.I)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous = '', ''
    else:
        _, text, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ' ':
        if not previous:
            value = 1.65
        elif previous.isspace() and '\n' not in previous:
            if len(previous) > 1:
                value = -1.4
            else:
                value = -0.27 if previous == ' ' else 0.2
        elif text.endswith('\\n'):
            value = 2.2
        elif text.endswith('\n'):
            value = 1.3
        elif YEAR_BOUNDARY.search(text):
            value = 1.3
        elif STRING_START.search(text):
            value = 1.6
        elif previous == ',':
            value = 0.06
        elif previous == '.':
            value = 0.1
    elif token == ',' and DAY_END.search(text):
        value = 0.9
    elif token.strip().casefold() in MONTH_SET and DAY_NUMBER.search(text):
        value = 0.7
    elif token == '\t':
        if not previous:
            value = -1.46
        elif previous and not previous.strip('\t'):
            value = -0.65 if len(previous) == 1 else -0.85
    elif token == '\xa0':
        continuation = len(previous) > 1 and previous.isspace()
        value = -1.3 if continuation and '\n' not in previous else -0.03
    elif token and not token.strip('\xa0'):
        value = -0.2
    elif token == ' &&':
        value = 0.4
    elif token == ' ||':
        value = 0.2
    return (doc, (text + token)[-160:], token), value

