Use the last three token strings to distinguish 'the only' and 'not only'
from restrictive 'only', and adjust its strength for auxiliaries, subjects,
prepositions and nearby contrast. 'Just' and 'simply' are weaker triggers.
A small multilingual lexicon and a short byte buffer recognize additional
spellings. This is a lexical heuristic, not a parser; other positions are zero.
"""
import re

READS = ()
DETERMINERS = set('the my your his her its our their whose'.split())
SUBJECTS = set('i you he she it we they'.split())
NEGATION = {'not', "n't", "'t", '’t', 'never'}
CONTRAST = {'but', 'yet', 'however'}
PREPOSITIONS = set('of for with in by from at into through without after'.split())
ROMANCE = re.compile(r'\b(el|la|de|que|di|della|il|una|los|las|per|da|sono|dal)\b')


def only_value(token, words):
    prev, before, third = words
