        value = 1.25
    elif prev in NEGATION:
        value = 0.65
    elif prev in {"'s", '’s'}:
        subjects = SUBJECTS | {'this', 'that', 'what', 'there', 'here'}
        value = -9.2 if before in subjects else 1.0
    elif prev == 'and' and before == 'if':
        value = -0.45                  # if and only if
    elif prev == 'and' and before in {'one', 'first', 'last'}:
        value = -1.7                   # one and only
    elif prev in CONTRAST:
        value = -7.8
    elif prev in {'will', 'would', 'could', "'d", '’d'}:
        value = -8.0
    elif prev in {'can', 'may', 'might', 'must', 'shall', 'should'}:
        value = -6.8
    elif prev in {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
                  "'m", '’m', "'re", '’re'}:
        value = -6.35
    elif prev in SUBJECTS:
        value = -6.5
    elif prev == 'to':
        value = -5.2
    elif prev in PREPOSITIONS:
        value = -3.0
    elif prev == 'if':
        value = -2.3
    elif prev.endswith('ing'):
        value = -3.3
    elif token == ' Only':
        value = -6.0
    else:
        value = -4.9
    # Nearby negation and contrast still modify the reading of 'only'.
    if prev not in NEGATION and before in NEGATION:
        value += 2.5
    elif prev not in NEGATION and third in NEGATION:
