    elif word in {'simply', 'merely'}:
        value = -0.6
    elif word == 'nur':
        value = -1.9 if prev == 'nicht' else -8.0
    elif word == 'ur' and re.search(r'\bnur$', text):
        value = -12.0
    elif word == 'только' or (word == 'олько' and text.endswith('только')):
        value = 0.9 if prev == 'не' else -4.0
    elif word in {'лишь', 'tylko', 'hanya', 'apenas'}:
        value = -3.0
    elif word in {'só', 'sólo'}:
        value = -7.5
    elif word == 'ó' and re.search(r'\bsó$', text):
        value = -10.0
    elif word == 'solo':
