            value = -2.0
        else:
            value = -8.5 if ROMANCE.search(text[:-4]) else -0.8
    elif word == 'olo' and re.search(r'\bsolo$', text):
        value = -11.0
    elif text.endswith(('solamente', 'soltanto')):
        value = -10.0
    elif text.endswith('uniquement'):
        value = -5.5
    elif text.endswith('seulement'):
        value = 0.8 if prev == 'pas' else -5.0
    elif word == 'chỉ':
        value = -1.0 if prev == 'không' else -6.0
    elif text.endswith(('只', '只有')):
        value = -3.4
    elif word == '仅':
        value = -2.4
    elif word == '只能':
        value = -1.0
    return (doc, (word, words[0], words[1]), joined), value

programs.haiku:
"""Explains layers.1.mlp.down_proj:554: a word-level "only" detector.

The component goes negative on the word "only" used as a restrictive adverb, as in
"can only", "is only", "only if", "with only". It is strongest after a modal verb, a bit
weaker after a preposition. It fires on the token that completes the word, so "soltanto"
fires on "anto" and "Nur" on "ur". Translations of "only" take the same role: "nur",
"soltanto", "sólo", "apenas", "chỉ", "tylko", "только", "лишь", and so on. Weaker negative
values go to "just", "simply" and "merely". "Only" right after "not" or "the" ("not only",
"the only") is near zero or slightly positive instead.

The carry is the last 40 characters of text, so each step is cheap.
"""

READS = ()

MODALS = {"can", "will", "would", "could", "should", "may", "might", "must"}
BE_HAVE = {"is", "are", "was", "were", "be", "been", "has", "have"}
PREPOSITIONS = {"with", "of", "in", "on", "for", "by", "to", "using"}
# Typical activation when the word completes the text (negative = the component's "only" direction).
WORD_VALUE = {
    "nur": -8.5, "soltanto": -9.5, "só": -8.5, "sólo": -7.0, "solo": -3.0,
    "solamente": -6.0, "esclusivamente": -3.7, "uniquement": -5.5, "seulement": -2.0,
    "apenas": -4.0, "chỉ": -4.5, "tylko": -3.5, "hanya": -3.2, "только": -2.9,
    "лишь": -2.3, "csak": -2.0, "just": -1.1, "simply": -0.6, "merely": -0.6,
}
# Chinese "only" words, which are not space-separated, so matched as whole tokens.
TOKEN_VALUE = {"只": -3.0, "仅": -2.4, "只有": -3.5}
# Words before "only" that make it near zero or slightly positive: "not only", "the only", "не только".
FLIP_BEFORE = {"not", "the", "не"}
FLIP_VALUE = 1.0


def _trailing_letters(s):
    i = len(s)
    while i > 0 and s[i - 1].isalpha():
        i -= 1
    return s[i:]


def _only_value(before):
    if before in FLIP_BEFORE:
        return FLIP_VALUE
    if before in MODALS:
        return -7.0
    if before in BE_HAVE:
        return -6.0
    if before in PREPOSITIONS:
        return -3.5
    return -5.0


def step(carry, prefix, upstream):
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    tail = "" if new_doc or carry is None else carry
    token = prefix.token_strings[-1]
    tail = (tail + token)[-40:]
    word = _trailing_letters(tail).lower()
    before = _trailing_letters(tail[: len(tail) - len(word)].rstrip()).lower()
    if word == "only" or (word == "только" and before in FLIP_BEFORE):
        value = _only_value(before) if word == "only" else FLIP_VALUE
    elif word in WORD_VALUE:
        value = WORD_VALUE[word]
    elif token.strip() in TOKEN_VALUE:
        value = TOKEN_VALUE[token.strip()]
    else:
        value = 0.0
    return tail, value

programs.sol:
"""Predict a negative formatting-boundary signal, not ordinary paragraph text.

At an empty line, indentation and code/comment markers receive a large negative
value; headings and list markers receive smaller ones. An empty comment, quote,
or diff line also counts as a boundary. A colon/open brace weakens the indentation
signal. Whitespace and a short comment prefix can carry it into the next token.
Literal backslash-n pairs are a separate, weaker boundary signal.
These fixed amplitudes approximate the pattern, not its token-specific variation.
"""
READS = ()
EMPTY_LINES = {'', '#', '##', '*', '>', '+', '-', '--', '//', '///'}
LINE_PREFIXES = {'', '#', '//', '///', '+', '-'}
IMPORTS = {'import', 'from', '#include', '#import', 'using'}
DECLARATIONS = {
    'public', 'private', 'protected', 'class', 'interface', 'struct',
    'enum', 'type', 'export', 'package', 'typedef', 'template',
}
FUNCTIONS = {'def', 'func', 'function', 'async'}
CONTROLS = {'if', 'else', 'for', 'while', 'switch', 'try', 'return'}
TYPES = {'void', 'int', 'float', 'double', 'bool', 'boolean', 'char',
         'string', 'static', 'final', 'let'}


def token_kind(s):
    if s and not s.strip(' \t'):
        return 'indent'
    x = s.lstrip(' \t')
    if x.startswith('/*'):
        return 'block_comment'
    if x.startswith('//') or x == '--':
        return 'comment'
    if x == '*':
        return 'star'
    if x.startswith('**'):
        return 'bold'
    if x.startswith(('@', '#[')):
        return 'decorator'
    if x.startswith('#') and x not in IMPORTS:
        return 'hash' if x == '#' else 'heading'
    if x in {'const', 'var'}:
        return 'variable'
    if x in IMPORTS:
        return 'import'
    if x in DECLARATIONS or x == 'namespace':
        return 'declaration'
    if x in FUNCTIONS:
        return 'function'
    if x in CONTROLS:
        return 'control'
    if x in TYPES:
        return 'type'
    if x.startswith(('```', '~~~')):
        return 'fence'
    if x in {'-', '+', '•', '>'}:
        return 'list'
    if x.isdecimal():
        return 'number'
    return 'other'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, age = '', 99
    else:
        _, tail, age = carry
    s = prefix.token_strings[-1]
    x = s.lstrip(' \t')
    kind = token_kind(s)
    parts = tail.rsplit('\n', 2)
    blank = (len(parts) == 3 and parts[1].strip() in EMPTY_LINES
             and parts[2].strip() in LINE_PREFIXES)
    value = 0.0
    if blank:
        age = 0
        before, marker, line = parts[0].rstrip(), parts[1].strip(), parts[2]
        opened = before.endswith((':', '{'))
        completed = before.endswith((';', '}'))
        code = (completed or any(c in before for c in '{}=')
                or any(w in before for w in ('\nimport ', '\nfrom ', '#!')))
        indented = bool(line)
        values = {'comment': -5.0, 'block_comment': -4.2,
                  'bold': -1.3, 'heading': -1.2, 'function': -1.8,
                  'control': -0.4, 'type': -0.7, 'fence': -1.0,
                  'number': -0.18, 'other': -0.06, 'decorator': -2.5}
        value = values.get(kind, 0.0)
        if kind == 'indent':
            value = -1.9 if opened else -4.3 if completed else -3.2
            if indented:
                value *= 0.7
        elif kind == 'star':
            value = -3.7 if marker == '*' or code else -0.2
        elif kind == 'hash':
            value = -5.1 if code or indented else -2.9
        elif kind == 'heading':
            if s.count('#') >= 6:
                value = -3.3
            elif before.endswith('`'):
                value = -2.3
        elif kind == 'import':
            value = -5.2 if completed else -2.4
        elif kind == 'declaration':
            value = -1.8 if indented else -3.6 if s.startswith('\t') else -2.7
            if x == 'namespace':
                value = -5.5
        elif kind == 'variable':
            value = -0.4 if indented else -4.0
        elif kind == 'list':
            value = -3.5 if marker in {'+', '-'} else -0.12 if opened else -0.75
            if marker == '>':
                value = -2.2
        elif kind == 'comment':
            if x == '--' and not (code or indented):
                value = -0.3
            elif len(x.strip()) > 12 and not x.strip('/ \r\n'):
                value = -1.4
        elif kind == 'block_comment' and len(x) > 12:
            value = -1.0
        if not indented and s.startswith('\t'):
            if kind in {'control', 'function', 'type', 'variable'}:
                value -= 1.2
        if '\n' in s and kind not in {'block_comment', 'comment', 'decorator'}:
            value = 0.0
    elif age == 1:
        if kind == 'type':
            value = -1.0
        elif kind == 'star':
            value = -1.4
    if (tail + s).endswith('\\n\\n') and s.endswith('n'):
        value = -1.6
    return (doc, (tail + s)[-160:], age + 1), value

programs.haiku:
"""Draft v3: only indentation or declaration-opener tokens after a blank line."""
READS = ()
OPENERS = ("import", "package", "public", "private", "protected", "#", "//", "###", "type", "func", "def", "class")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    tok, prev = toks[-1], toks[-2]
    if "\n\n" in prev:
        if tok.strip(" \t") == "" and tok:
            return None, -4.0
        if tok.lstrip().startswith(OPENERS):
            return None, -3.0
    return None, 0.0

programs.sol:
"""Dutch word-piece activity.

Compare recent words using corpus frequencies in European languages. In Dutch
context, unfinished word pieces get stronger values than very common complete
words. Evidence spans four or twelve recent words; Afrikaans function words
provide a related-language cue. Otherwise only distinctly Dutch words fire.
"""
import re
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
LANGUAGES = ('nl', 'en', 'de', 'fr', 'es', 'it', 'pt')
AFRIKAANS_FUNCTION_WORDS = {
    'nie', 'vir', 'hy', 'sy', 'hulle', 'hul', 'deur', 'baie',
    'hierdie', 'daardie', 'slegs', 'reeds', 'soos',
}

# Frequency of the most common Dutch word beginning with each spelling.
DUTCH_PREFIX = {}
for word in top_n_list('nl', 60000):
    if word.isalpha():
        frequency = zipf_frequency(word, 'nl')
        for length in range(1, len(word) + 1):
            DUTCH_PREFIX.setdefault(word[:length], frequency)


@lru_cache(maxsize=100000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def strength(context, advantage, incomplete, other, length, beginning):
    if context <= 0.99:
        return 0.0 if advantage <= 3.85 else 1.19
    if incomplete <= 0.03:
        if not length:
            return 0.13
        if beginning > 7.40:
            return 0.77
        if other <= 2.82:
            return 1.45
        return 1.05 if advantage <= -0.36 else 2.34
    if length > 4:
        return 2.48
    if advantage <= -1.51:
        return 2.22
    if beginning <= 4.77:
        return 1.76 if advantage <= -0.14 else 3.96
    return 4.04


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', [])
    _, word, history = carry
    history = history.copy()
    token = prefix.token_strings[-1]
    for part in re.findall(r'[^\W\d_]+|[^\w]+|[\d_]+', token):
        if part.isalpha():
            word += part.lower()
        elif word:
            history.append(word)
            history = history[-12:]
            word = ''

    context = 0.0
    if history:
        word_frequencies = [frequencies(w) for w in history]
        evidence = []
        for window, penalty in ((4, 0.0), (12, 0.5)):
            recent = word_frequencies[-window:]
            average = [sum(max(1, f[j]) for f in recent) / len(recent)
                       for j in range(len(LANGUAGES))]
            evidence.append(average[0] - max(average[1:]) - penalty)
        context = max(evidence)
        # These function words provide an additional cue to Afrikaans.
        english_advantage = sum(f[0] - f[1] for f in word_frequencies)
        if (any(w in AFRIKAANS_FUNCTION_WORDS for w in history)
                and english_advantage / len(history) > 1):
            context = max(context, 1.5)
    spelling = token.strip().lower()
    if spelling.isalpha():
        f = frequencies(spelling)
        incomplete = DUTCH_PREFIX.get(spelling, 0) - f[0]
        other = max(f[1:])
    else:
        incomplete = other = 0.0
    f = frequencies(word) if word else (0,) * len(LANGUAGES)
    value = strength(context, f[0] - max(f[1:]), incomplete, other,
                     len(word), DUTCH_PREFIX.get(word, 0))
    return (doc, word, history), value

"""A TAKE-family detector, sensitive to grammar and token boundaries.

Take, takes, took, taking and taken are negative. 'Have taken' is stronger
than passive 'be taken'; impersonal 'it takes/took' is much weaker.
Split tak-/took- spellings can be stronger still, including inside names.
Some compound completions are weaker, and t+ave has the opposite sign.
The program keeps only a short text tail and resets it at document changes.
It does not try to explain the component's smaller multilingual responses.
"""
import re

READS = ()
FORMS = {'take': -4.4, 'takes': -3.4, 'took': -4.1,
         'taking': -4.1, 'taken': -2.5}
MODALS = {'will', 'would', 'can', 'could', 'may', 'might', 'must', 'should'}
PERFECT = {'have', 'has', 'had', 'having', 've'}
PASSIVE = {'be', 'is', 'are', 'was', 'were', 'been', 'being'}
AGENTS = {'you', 'they', 'he', 'she', 'who', 'person', 'speaker'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    s = token.lower()
    word = s.strip(' _-')
    value = FORMS.get(word, 0.0)
    if word in FORMS:
        words = re.findall(r'[a-z]+', history)[-5:]
        last = words[-1] if words else ''
        if word == 'taken' and PERFECT.intersection(words[-3:]):
            if not PASSIVE.intersection(words[-2:]):
                value = -4.8
        if word == 'take':
            if last in {'to', 'and', 'or'}:
                value = -5.1
            elif last in MODALS or last in {'i', 'we'}:
                value = -3.8
        if word in {'take', 'takes', 'took'}:
            if last in AGENTS:
                value = -5.3
            if re.search(
                r'\bit(?:\s+(?:will|would|can|could|may|might|must|should|'
                r'does|did|not|never|only|also|just|certainly))*\s*$', history
            ):
                value = -0.9
        if word == 'taking' and last in {'by', 'is'}:
            value = -3.2
        if token.strip()[:1].isupper():
            value *= 0.9 if token[:1].isspace() else 0.8
    elif word == 'tak':
        value = -2.1
    elif word in {'mistake', 'mistakes', 'mistaken'}:
        value = -3.1 if word.endswith('n') else -1.3
    elif word in {'undertake', 'undertaking', 'undertaken'}:
        value = -5.3 if word == 'undertake' else -2.7

    # Only a token without leading whitespace continues the old spelling.
    split = False
    if history.endswith('t'):
        if s.startswith('ook'):
            value, split = -9.0, True
        elif s in {'ak', 'aki', 'aks'}:
            value, split = (-9.0 if token.isupper() else -5.5), True
        elif s.startswith(('ake', 'aki')):
            value, split = -7.5, True
        elif s in {'ave', 'aves', 'av'}:
            value = 1.6 if s == 'av' else 5.0
    elif history.endswith('ta') and s in {
        'k', 'ke', 'kes', 'ken', 'ki', 'ks'
    }:
        value, split = -7.0, True
    elif history.endswith('tak') and s in {'e', 'es', 'en', 'er', 'ers'}:
        value, split = (-9.0 if token.isupper() else -6.0), True
    elif ((history.endswith('to') and s.startswith('ok'))
          or (history.endswith('too') and s.startswith('k'))):
        value, split = -9.0, True
    if split:
        spelling = re.search(r'[a-z]+$', history)
        spelling = (spelling.group() if spelling else '') + s
        if spelling.startswith(('intake', 'caretaker', 'stake', 'uptake')):
            value = -2.7
        elif spelling.startswith('partak'):
            value = -11.5
        elif spelling.startswith(('overtook', 'undertook')):
            value = -6.5
    return (doc, (history + s)[-96:]), value

"""A boundary/continuation detector, not a token lookup.

Positive responses mark assistant headers, document openings, and Unix root
paths. Negative responses favor split Latinate prefixes, especially a repeated
consonant across the split. Two encoding artifacts (NUL-separated text and
repeated middle dots) have their own simple rules. Familiar "as ..."
constructions are distinguished too. State resets at document boundaries;
most tokens receive zero. This deliberately omits fine lexical preferences.
"""
import regex as re
from anyascii import anyascii

READS = ()
ROOTS = {'workspace', 'usr', 'opt', 'tmp', 'dev', 'home', 'root',
         'etc', 'var', 'bin', 'Users'}
LATIN_PREFIX = re.compile(r'(?:a[bcdfgjklmnprstv]|a([bcdfglmnprst])\1|ob)$')


REPEAT_VOWEL = -0.890
REPEAT_BARE = -1.398
HARD_C = -1.576
ADJUST = -1.628
SOFT_C = -2.856
DOUBLE_END = -0.164
OTHER_CONSONANT = -0.088
READJUST = -3.277
NASAL_REPEAT = -0.437

def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        p, pp = '', ''
        value = 2.71 if t == '<|endoftext|>' else 0.20
    else:
        p, pp = carry[1:]
        value = 0.0
    s, q = t.strip(), p.strip()
    if p == '<|endoftext|>':
        value = 0.30
        if s == 'package':
            value = 2.62
        elif s.startswith(('/*', '"""')):
            value = 2.15
        elif s.startswith('#') or s in {'import', 'using'}:
            value = 0.72
    if p == '<|im_start|>' and t == 'assistant':
        value = 0.82

    # Root names following a slash; fused /workspace after a line break.
    if s in ROOTS and p.rstrip().endswith('/'):
        value = {'opt': 1.65, 'tmp': 0.83, 'dev': 0.76,
                 'root': 0.72, 'etc': 0.83, 'Users': 1.75,
                 'bin': 0.90}.get(s, 1.20)
    elif t == '/workspace' and '\n' in p:
        value = 0.38
    elif t in {'/local', '/lib'} and q in {'usr', '/usr', '/local'}:
        value = 1.15 if t == '/local' else 0.72
    elif t == '/.' and q in {'root', '$USER'}:
        value = 0.41

    # Different grammatical continuations of "as" have opposite signs.
    if q.lower() == 'as' and t.startswith(' '):
        word = s.lower()
        if word == 'soon':
            value = -1.08
        elif word == 'compared':
            value = -0.36
        elif word in {'in', 'with', 'before', 'needed', 'required', 'long'}:
            value = 1.7 if q == 'As' else 0.85

    # A consonant repeated across a short prefix/stem split is negative.
    # c/q and d/j cover familiar assimilations as in acquire and adjust.
    if t and p and t[0].isalpha() and p[-1].isalpha():
        a = re.split(r'[^\w]', p.lower())[-1]
        b = t.lower()
        # Apply the same orthographic rule to Cyrillic via transliteration.
        if re.search(r'\p{Script=Cyrillic}', a + b):
            a, b = anyascii(a), anyascii(b)
        if LATIN_PREFIX.fullmatch(a):
            if a[-1] == b[0]:
                has_vowel = any(c in 'aeiouy' for c in b)
                value = REPEAT_VOWEL if has_vowel else REPEAT_BARE
            elif a[-1] == 'c' and b[0] == 'q':
                value = HARD_C
            elif a[-1] == 'd' and b[0] == 'j':
                value = ADJUST
            elif a[-1] == 's' and b[0] == 'c' and b[1:2] in {'e', 'i', 'y'}:
                value = SOFT_C
            elif len(a) > 2:
                value = DOUBLE_END
            elif b[0] not in 'aeiouy':
                value = OTHER_CONSONANT
        elif a.endswith('ad') and b[0] == 'j':
            value = READJUST
        elif a in {'com', 'kom', 'som', 'sum', 'om'} and b[0] == 'm':
            value = NASAL_REPEAT

    if t == '\x00' and '\x00' in pp:
        value = -1.43
    if t and set(t) == {'·'} and p and set(p) == {'·'}:
        value = 1.88
    return (doc, t, p), value

"""Approximate a FOR / FOUR feature, with a near-zero background.

English FOR and several translations receive negative values. Selected verb
phrases weaken the response; case and code indentation also modify it.
Recent word frequencies distinguish French 'pour', Italian 'per', and
Bulgarian 'за' from their other uses.

Digit FOUR is more negative in letter-and-digit identifiers, less negative
inside longer numerals, and positive in 64-bit numeric type names. Words for
four, Roman IV, April and Thursday also receive negative values. State resets
at document boundaries. Many small incidental lexical effects are omitted.
"""
import re
from wordfreq import zipf_frequency
import wordnet

READS = ()

# Words meaning 'for', not a table of tokenizer identities.
FOR_TRANSLATIONS = {
    'pour': -4.2,       # French
    'para': -2.05,      # Spanish / Portuguese
    'für': -1.75,       # German
    'för': -1.7,        # Swedish
    'для': -1.5,        # Russian
    'dla': -1.45,       # Polish
    'voor': -0.92,      # Dutch
    'pentru': -2.25,    # Romanian
    'untuk': -1.4,      # Indonesian / Malay
    'ل': -1.25,        # Arabic FOR/TO prefix, with/without the article
    'لل': -1.25,
}
FOUR_WORDS = {'four', 'fourth', 'vier', 'cuatro', 'quatre', '四', '４'}
# Predicates that conventionally select a FOR complement.
FOR_SELECTORS = {'look', 'search', 'responsible', 'suitable', 'eligible', 'design'}


def language_score(text, language):
    words = re.findall(r"[^\W\d_]+", text.lower())[-20:]
    return sum(zipf_frequency(w, language) for w in words)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        _, previous, recent = carry
    s = prefix.token_strings[-1]
    w = s.strip()
    low = w.lower()
    value = -0.01
    if w == '4':
        value = -1.08
        if previous[-1:].isdigit():
            value = -0.82
            if re.search(r'(?:u?int|float|bits?)6$', recent, re.I):
                value = 0.7
        elif previous[-1:].isascii() and previous[-1:].isalpha():
            value = -2.7
        elif previous.endswith('.'):
            value = -0.76
        if previous.endswith('_'):
            value = -1.8
        if not previous:
            value = 0.35
    elif low in FOUR_WORDS:
        value = -0.9
    # Fourth month, fourth ISO weekday, and Roman numeral four.
    elif w in {'April', 'Apr', 'Thursday', 'Thu', 'IV'}:
        value = -0.6
    elif low == 'for':
        match = re.search(r'([^\W\d_]+)$', recent)
        word = match.group(1) if match else ''
        lower_word = word.lower()
        if w == 'For':
            value = -1.1 if word else -0.05
        elif w == 'FOR':
            value = -1.5
        elif '\t' in s:
            value = 0.35
        elif not previous:
            value = -0.65
        elif previous.isspace():
            value = -0.1
        else:
            value = -1.45 if s.startswith(' ') else -0.65
            bases = set(wordnet.base_forms(lower_word)) | {lower_word}
            if bases & FOR_SELECTORS:
                value = -0.6
            if lower_word in {'known', 'ready'}:
                value = -0.25
            if 'wait' in bases:
                value = 0.0
    elif low in FOR_TRANSLATIONS:
        value = FOR_TRANSLATIONS[low]
        if low in {'ل', 'لل'} and not s.startswith(' '):
            value = -0.25
        if low == 'pour':
            if s == 'pour':
                value = -0.6
            elif language_score(recent, 'fr') < language_score(recent, 'en'):
                value = -0.2
            elif w == 'Pour':
                value = -3.2
    elif low == 'per':
        italian = language_score(recent, 'it')
        other = max(language_score(recent, lang) for lang in ('en', 'es', 'fr'))
        value = -0.1
        if italian > other:
            if s == ' per':
                value = -4.3
            elif w == 'Per':
                value = -3.1
    elif low == 'за':
        bulgarian = language_score(recent, 'bg')
        other = max(language_score(recent, lang) for lang in ('ru', 'uk'))
        value = -3.3 if bulgarian > other else -0.1
    elif (low in {'α', 'ια', 'για'}
          and re.search(r'(?<!\w)για$', (recent + s).lower())):
        value = -5.5
    elif w in {'为', '为了', '為'}:
        value = -0.5
    elif w == 'ля' and previous.strip().lower() == 'д':
        value = -3.5
    return (doc, s, (recent + s)[-150:]), value

"""Recognize declaration boundaries in source code and structured text.

Access modifiers respond most strongly, especially after a completed block,
annotation, or documentation comment. Function/type declarations and imports
are weaker. The parser ignores diff marks and printed source-line numbers,
and treats escaped newlines as line breaks. JSON string values and an opening
'Title:' document header have their own small structural rules.
"""
import re

READS = ()
ACCESS = {'public', 'private', 'protected', 'internal'}
MODIFIERS = ACCESS | {'static', 'inline', 'virtual', 'override', 'overriding',
                      'async', 'pub', 'pub(crate)', 'unsafe', 'export'}
DECLARATIONS = {
    'func': 6.4, 'function': 2.1, 'def': 1.4, 'fn': 1.7,
    'impl': 6.5, 'pub': 3.5, 'extern': 4.0, 'export': 4.7,
    'procedure': 3.0, 'theorem': 2.1, 'instance': 1.5,
}
ANNOTATIONS = {'Override': 5.5, 'staticmethod': 7.0, 'classmethod': 7.0}
WORDS = MODIFIERS | set(DECLARATIONS) | set(ANNOTATIONS) | {
    'import', 'this', 'self', 'alias', 'Title', '@Override'}
PUNCTUATION = {':', ' "', ' (', ' (!', ' ($', ' ("', '(int', '(self'}


def source_line(line):
    """Remove a grep/listing prefix or a diff margin, not source syntax."""
    line = re.sub(r'^\S[^\n]*?:\d+:\s*', '', line)
    return re.sub(r'^\s*(?:[+-]\s*)?(?::?\d+\s*[:\t|])?', '', line)


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    raw = '' if carry is None or carry[0] != doc else carry[1]
    state = (doc, (raw+s)[-800:])
    word = s.strip()
    if word not in WORDS and s not in PUNCTUATION:
        return state, 0.0
    text = raw.replace('\\n', '\n').replace('\\t', '\t')
    text = text.replace('\\r', '').replace('\r', '')
    lines = text.split('\n')
    previous = [source_line(x).strip() for x in lines[:-1]]
    previous = [x for x in previous if x]
    last = previous[-1] if previous else ''
    code = [x for x in previous if not x.startswith('//')]
    closed = bool(code and code[-1].endswith('}'))
    line = lines[-1] + s[:len(s)-len(s.lstrip())]
    numbered = bool(re.match(r'^\s*:?\d+\s*[:\t|]|^\S.*?:\d+:', line))
    lead = re.sub(r'^@@.*?@@\s*', '', source_line(line))
    lead = re.sub(r'^(?://|\*)\s*', '', lead).strip(' `')
    lead = re.sub(r'^(?:@\w+(?:\([^\n]*?\))?|\[[^\n]*?\])\s*', '', lead)
    initial = not lead.strip()
    boundary = initial or lead.rstrip().endswith(('{', '}', ';'))
    words = lead.split()
    modifier = words[-1] if words else ''
    separated = s[:1].isspace() or not text or not (
        text[-1].isalnum() or text[-1] == '_')
    value = 0.0
    if separated and word in ACCESS:
        allowed = boundary or text.rstrip().endswith('`')
        if word == 'internal':
            allowed = boundary and ('{' in text or 'namespace' in text)
        if allowed:
            value = 4.5 if word == 'private' else 6.4
            if word == 'internal':
                value = 10.0
            if closed or last.endswith('*/') or last.startswith('@'):
                value = (8.5 if closed else 5.8) if word == 'private' else 9.9
            if last.startswith('///'):
                value = 11.2
            if '#include' in text or re.search(r'\b(public|private|protected):', text):
                value = 3.5  # C++ access labels, rather than Java/C# members.
        else:
            value = -0.15
    elif separated and word in ('static', 'inline', 'virtual', 'override'):
        if modifier in ACCESS:
            value = 5.5 if modifier == 'private' else 8.6
        elif word == 'inline' and modifier == 'static':
            value = 6.7
        elif boundary:
            value = 7.1 if closed else (6.0 if last.endswith('*/') else 3.6)
        elif text.rstrip().endswith('`'):
            value = 5.5
        elif word == 'static' and text.rstrip().endswith("'"):
            value = 2.6
        elif word == 'static' and modifier == 'import':
            value = 2.4
    elif separated and word in DECLARATIONS:
        if boundary or (words and all(w in MODIFIERS for w in words)):
            value = DECLARATIONS[word]
            if numbered and word in ('func', 'pub', 'extern', 'impl', 'export'):
                value = {'func': 2.7, 'pub': 2.8, 'extern': 2.8,
                         'impl': 4.5, 'export': 1.9}[word]
            if word == 'fn' and modifier.startswith('pub'):
                value = 2.6 if numbered else 3.1
            if word == 'pub' and last.endswith(']'):
                value = 5.5
            if word == 'export' and ('#!' in text or re.search(r'\bexport [A-Z_]+=', text)):
                value = 0.0  # Shell environment variables are not module exports.
    elif word == 'import' and separated:
        if re.match(r'from\s+', lead):
            value = 1.5
        elif initial:
            value = 0.5 if numbered else (1.7 if ';' in text[-300:] else -0.1)
    elif word in ANNOTATIONS and text.rstrip().endswith('@'):
        value = ANNOTATIONS[word]
    elif word == '@Override':
        value = 6.2
    elif word in ('this', 'self') and separated:
        if initial or re.search(r'\b(return|yield|if|elif)\s*$', line):
            value = 1.05
        elif re.search(r'[($=\[]\s*$', line):
            value = 0.9
    elif word == 'alias' and text.endswith('type'):
        value = 4.4  # The second token of Swift's typealias declaration.
    elif word == 'overriding' and initial:
        value = 1.9  # Ada's dispatch modifier.
    if s.startswith(' (') or s == '(int':
        control = re.search(r'\b(if|for|foreach|while|switch|catch)\s*$', line)
        if control:
            value = 1.6 if control[1] in ('for', 'foreach', 'switch') else 1.0
    if s == '(self':
        value = 1.05
    if s == ' "' and text.rstrip().endswith(':'):
        value = 0.42
    if not raw and word not in ('procedure', 'theorem', 'instance'):
        value = 0.0
    if word == 'Title' and not raw:
        value = 0.75
    if s == ':' and raw.strip() == 'Title':
        value = 13.0
    return state, value

programs.haiku:
"""Declaration openers: fires on the keyword that opens a class member or function
declaration in source code, when that keyword starts a line.

The strongest case is an access modifier beginning a member in Java, C#, C++ or PHP:
`public` and `protected` (about 9), `private` and `internal` (about 6). Also strong:
`static` or `override` right after an access modifier (about 8), and a line-opening
`static`, `pub`, `impl` (about 5 to 6). Annotations that introduce a method (`@Override`,
`@staticmethod`) give about 6. Other languages' declaration keywords are weaker: `func`
(Go) about 5, `export` about 4, `function` about 2, `fn` and `def` about 1.5, `import`
about 1.3. A `(` right after `for` or `if` gives about 1.5. Everything else is 0.
The values are typical activations at those tokens, not fitted per token.
"""

READS = ()

# Access modifiers and member keywords that open a line (value = typical activation).
LINE_OPENERS = {
    "public": 9.0, "protected": 9.0, "private": 6.0, "internal": 6.0,
    "pub": 5.0, "static": 5.0, "impl": 6.0,
}
# Declaration keywords of other languages, weaker.
DECL_KEYWORDS = {"func": 5.0, "export": 4.0, "function": 2.0, "fn": 1.5, "def": 1.5, "import": 1.3}
# Annotations / decorators that introduce a method.
ANNOTATIONS = {"@Override": 6.0, "Override": 6.0, "staticmethod": 6.0, "classmethod": 6.0}
# A modifier that, after an access modifier, opens the member.
ACCESS_WORDS = {"public", "protected", "private", "internal", "pub"}
AFTER_ACCESS = {"static": 8.0, "override": 8.0}


def _starts_line(strings, i):
    """True if only whitespace comes before token i on its line (a real or escaped newline)."""
    text = "".join(strings[max(0, i - 12):i])
    real, escaped = text.rfind("\n"), text.rfind("\\n")
    if max(real, escaped) < 0:
        return False
    start = real + 1 if real > escaped else escaped + 2
    return text[start:].strip() == ""


def _previous_word(strings, i):
    j = i - 1
    while j >= 0 and strings[j].strip() == "" and "\n" not in strings[j]:
        j -= 1
    return strings[j].strip() if j >= 0 else ""


def step(carry, prefix, upstream):
    s = prefix.token_strings
    i = len(s) - 1
    word = s[i].strip()
    before = _previous_word(s, i)
    if word in AFTER_ACCESS and before in ACCESS_WORDS:
        return None, AFTER_ACCESS[word]
    if word == "Override" and before == "@":
        return None, 6.0
    if word == "(" and before in ("for", "if"):
        return None, 1.5
    if _starts_line(s, i):
        for table in (LINE_OPENERS, DECL_KEYWORDS, ANNOTATIONS):
            if word in table:
                return None, table[word]
    return None, 0.0

programs.sol:
"""An approximate detector of opening collection literals and a few phrases.

Braces and brackets respond differently in assignments, fields, function calls,
indexing, and blocks. Quotes, newlines, and Python-like syntax refine this.
There are smaller phrase/comma rules for English and Japanese. Most response
levels are training averages, with simple fallbacks. This is not a simulation
of the network. Unrecognized tokens get zero.
"""
import regex as re

READS = ()

CONJUNCTION_COMMAS = {
    'that': -0.58,
    'and': -0.59,
    'but': -1.52,
    'so': -0.55,
    'or': -0.04,
    'as': -0.00,
    'yet': -0.19,
}

PYTHON_ASSIGNMENT = {
    'dict': (4.75, 1.17),
    'list': (6.54, 4.28),
}

# Each triple is: plain opener, quoted/escaped opener, opener with newline.
LITERALS = {
    'dict': {
        'argument': (0.67, 1.39, 1.21),
        'assignment': (0.98, 1.49, 1.64),
        'attached': (-0.06, 0, 0.06),
        'element': (1.13, 1.01, 1.44),
        'field': (0.79, 0.96, 1.53),
        'indented': (1.0, 0.8, 0.1),
        'line_start': (-0.34, 0.57, 0.06),
        'other': (0.09, 0.08, -0.02),
        'quoted_field': (2.39, 1.39, 1.55),
        'return': (0.68, 1.44, 1.24),
    },
    'list': {
        'assignment': (2.19, 2.89, 3.67),
        'attached': (-0.03, 0, 0.89),
        'element': (1.71, 2.91, 2.74),
        'field': (1.53, 2.22, 3.33),
        'indented': (0.18, 0.77, 2.13),
        'line_start': (0.9, 0, 2.03),
        'other': (0.27, 1.22, 1.31),
        'quoted_field': (4.69, 3.79, 4.37),
        'return': (1.95, 0, 0),
    },
}

def response(s, prev, tail):
    """tail is the text before the current token (at most 160 characters)."""
    token = s.strip()
    previous = prev.strip()
    if token == ',':
        if previous.lower() in {'that', 'and', 'but', 'so', 'or', 'as', 'yet'}:
            return CONJUNCTION_COMMAS[previous.lower()]
        if re.search(r'\b[Tt]hat is$', tail):
            return 0.79
        return -0.01
    if token.lower() == 'this' and s.startswith(' '):
        if previous.lower() in {
            'in', 'with', 'during', 'of', 'for', 'at', 'on', 'from', 'to', 'by'
        }:
            return -0.89 if previous[:1].isupper() else -0.11
    if token.lower() == 'particular' and previous.lower() == 'in':
        return 0.88
    if token.lower() == 'also' and previous.lower() == 'see':
        return 2.48
    if token == '、':
        if previous.endswith('は'): return 0.93
        if previous.endswith('も'): return 0.67
        if re.search(r'[\p{Hiragana}\p{Katakana}]', prev): return 0.27
        return -0.02
    if token == 'また':
        return 1.78
    if token == '<' and previous == '#include':
        return 1.52
    if token.startswith('#['): return -0.47
    # Only punctuation tokens that END in an opening delimiter (possibly
    # followed by a quote, backslash, or newline) start a literal here.
    m = re.fullmatch(r'([=(:,;\]}]*)([\[{(])([\'"\\]*)(\s*)',token)
    if not m:
        if token in {'[[', '[-'}:
            return 1.79 if token == '[[' else 0.65
        return 0.0
    before,op,quote,_ = m.groups()
    python_syntax = bool(re.search(
        r'\b(?:def|elif|except|lambda|None|True|False)\b|'
        r'\b(?:np|pd|torch|self)\.|\bprint\(|\bimport \w|'
        r'\bfor \w+ in\b', tail))
    # Plain identifier assignments are another Python-like cue.
    python_like = python_syntax
    math_like = bool(re.search(
        r'\$|≈|\b(?:Thus|Therefore|Continuing|Divided)\b|'
        r'\\(?:frac|sum|sqrt)\b', tail))
    line = tail.replace('\\n','\n').split('\n')[-1]
    assignment = re.fullmatch(
        r'\s*(?:\d+\t\s*)?([A-Za-z_]\w*(?:\.\w+|\[[^\n]*\])*)\s*=',
        line + before)
    if assignment:
        name = assignment[1]
        python_like = python_like or (
            not math_like and ('_' in name or '.' in name or len(name) > 1)
        )
    # Ordinary parentheses are not collection constructors. Nested ones can be.
    if op == '(':
        if '\n' in s:
            return 1.14 if s[:1].isspace() else 0.08
        if quote:
            if not s[:1].isspace(): return -0.02
            return 0.61 if quote.replace('\\', '') else 0.19
        if '=' in before or previous == '=': return 0.38
        if '(' in before or previous in {'(', ',', 'return', '+', '*', '&&', '||'}:
            return 0.62
        if previous == 'that': return -0.64
        return 0.0
    kind = 'dict' if op == '{' else 'list'
    form = 1 if quote else 0
    if '\n' in s: form = 2
    # Nested List expressions in Mathematica box notation.
    if op == '[' and previous.startswith('[List'):
        return 1.58 if quote else 4.34
    if op == '[' and not s[:1].isspace() and not before and quote:
        return -0.04
    # Unspaced attribute braces are unlike Python collection literals.
    if op == '{' and '=' in before and not python_syntax:
        return 0.51
    if op == '[' and '(' in before and not s[:1].isspace():
        if before.count('(') > 1: return 2.34
        if previous.lower().lstrip('.') in {'array', 'series', 'join', 'set', 'list',
                                    'tuple', 'concatenate', 'tensor', 'extend'}:
            return 7.26
        return 5.04 if python_syntax else 3.19
    # Consecutive bracketed status/log lines.
    if op == '[' and prev.endswith(']\n'):
        return 1.66
    if '=' in before or previous.endswith('='):
        if form == 0 and python_like and (assignment or '=' in before):
            return PYTHON_ASSIGNMENT[kind][int('=' in before)]

        context = 'assignment'
    elif ':' in before or previous.endswith(':'):
        context = 'quoted_field' if re.search(r"['\"]:$", previous) else 'field'
    elif previous == 'return':
        if python_like: return 5.04 if kind == 'dict' else 4.00
        context = 'return'
    elif op == '{' and (previous.endswith(')') or previous in {'else','try','finally','do','=>'}):
        return -0.04
    elif ',' in before or previous.endswith(','):
        context = 'element'
    elif '(' in before:
        context = 'argument'
    elif (s.startswith((' ', '\n')) and tail.rstrip().endswith(('=', ':', ','))):
        context = 'element'
    elif not tail or tail.endswith('\n') or not tail.split('\n')[-1].strip():
        context = 'line_start' if not s[:1].isspace() else 'indented'
    elif re.fullmatch(r'\s*\d+\t\s*', line):
        context = 'indented'
    elif not s[:1].isspace() and not before and not quote:
        context = 'attached'
    else:
        context = 'other'
    if context == 'argument' and s[:1].isspace() and kind == 'list':
        return 0.12
    return LITERALS[kind].get(context, (0.0, 0.0, 0.0))[form]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, prev = "", ""
    else:
        _, tail, prev = carry
    s = prefix.token_strings[-1]
    value = response(s, prev, tail)
    return (doc, (tail + s)[-160:], s), float(value)

