"""layers.1.mlp.down_proj:563 -- an "opening bracket that starts a data literal" detector.

What it does: the component is near zero almost everywhere and spikes on an opening
square or curly bracket that begins a list, array, or JSON/dict value in code or
structured text, e.g. `column_values = [`, `"view_range": [`, `np.array([`, `{"`.
It is strongest for `[` that opens a list right after `=`, `:`, `,`, `(` or a JSON key
`":`, and weaker for `{` and for `[` at the start of a line. Subscripts such as `data[`
get about zero. Clause-linking words get a small negative value:
the comma in `So,` / `But,` / `that,` and `this` in `In this paper`. A `(` that opens
an operand after `==`, `&&`, `=` and similar gets a moderate value.

Only the previous token and the current token are read.
"""

READS = ()


def _prev_text(prefix):
    """The token before the current one, or "" at the start of a document."""
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[-2]


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = _prev_text(prefix)
    last = prev[-1:]  # "" at a document start
    if "[" in cur or "{" in cur:
        is_square = "[" in cur
        spaced = cur[:1] == " "
        if is_square and cur in ("([", "=["):
            value = 5.0  # a list handed straight to a call or assignment
        elif prev.endswith('":'):
            value = 4.0 if is_square else (1.4 if spaced else 0.4)  # JSON value
        elif last == "\n":
            value = 1.0 if is_square else 0.4  # bracket opening a line
        elif last and (last.isalnum() or last in ")]_"):
            value = 0.2 if spaced else 0.0  # subscript-like, e.g. data[
        elif last and last in "=:,(":
            value = 1.5 if is_square else 0.9  # value position in code
        else:
            value = 0.3 if is_square else 0.1
    elif cur.lstrip()[:1] == "(" and prev.endswith(("==", "&&", "||", "except", " =")):
        value = 0.8  # a parenthesis opening an operand after an operator
    elif cur == "," and prev in ("So", "that", "But", "And"):
        value = -0.8
    elif cur == " this" and prev == "In":
        value = -1.2
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""Approximate a proposition-introduction signal: reporting and evidence.

Large positive predictions mark 'that' after an assertion, observation, or
belief, 'like' after seeming/looking, and commas closing an attribution.
The rules contrast these with relative, demonstrative, and purpose 'that'.
Chinese reporting predicates and their following commas are also positive;
ordinary Chinese clause commas are negative. Continuing chat speaker headers
are mildly positive, unlike a new document's initial user header. Other explicit
complementizers share the positive signal. Chinese discourse words and
demonstratives get small lexical baselines. Unrecognized tokens predict zero.
A short byte buffer supplies context and resets at document boundaries.
"""
import regex as re
from functools import lru_cache
import wordnet
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
REPORT = set('say tell report state announce declare claim argue conclude '
             'indicate demonstrate show reveal find observe learn discover '
             'confirm establish prove suggest explain mention note write warn '
             'acknowledge admit assert allege contend rule hold hypothesize '
             'propose predict forecast suspect opine submit notify assure '
             'inform agree describe determine affirm posit postulate estimate '
             'corroborate intimate testify read add comment convince point'.split())
THOUGHT = set('think believe know understand realize recognize remember recall '
              'feel see hear seem'.split())
HYPOTHETICAL = set('suppose assume imagine expect hope'.split())
DIRECTIVE = set('ensure check verify test require need guarantee consider'.split())
EVIDENCE_NOUN = set('idea belief opinion impression conclusion observation '
                    'argument suggestion possibility likelihood evidence proof '
                    'sense question doubt news rumor rumour guess lesson point '
                    'statement assertion proposition hypothesis assumption testimony '
                    'view conviction notion contention allegation suspicion axiom'.split())
FORMAL_ZH = set(
    '表示 指出 认为 显示 介绍 预测 强调 表明 提醒 获悉 得知'.split()
)
HEARSAY_ZH = set('据了解 据悉 据报道 据统计'.split())

@lru_cache(maxsize=8192)
def roots(word):
    return set(wordnet.base_forms(word)) | {word}


def proposition(words):
    """Use the predicate or assertion noun just before English 'that'."""
    if not words:
        return 0.05
    last = words[-1]
    lemmas = roots(last)
    if lemmas & DIRECTIVE or last in {'so', 'such'}:
        return 0.04
    if last in {'but', 'in', 'at', 'after', 'before', 'to', 'as', 'if', 'with'}:
        return -0.2
    if last in {'except', 'given', 'provided'}:
        return 0.0
    if last in {'of', 'on', 'for', 'from', 'than', 'about'}:
        return -0.05
    if last in {'mean', 'means', 'meaning', 'fact'}:
        return 0.25
    if lemmas & {'imply', 'notice'} or last == 'note':
        return 0.4
    if lemmas & HYPOTHETICAL:
        return 0.3
    nominal = len(words) > 1 and words[-2] in {'the', 'these', 'those', 'some', 'a'}
    if lemmas & REPORT and not nominal:
        return 1.2
    if lemmas & THOUGHT:
        return 0.85
    if last in {'is', 'was', 'be', 'are', 'were', 'been'}:
        if any(roots(w) & EVIDENCE_NOUN for w in words[-5:-1]):
            return 1.3
        if any(w in {'problem', 'issue', 'difference', 'reason', 'thing'}
               for w in words[-4:-1]):
            return 0.15
        return 0.55
    if lemmas & EVIDENCE_NOUN:
        return 0.7
    if last in {'clear', 'obvious', 'apparent', 'likely', 'true', 'sure'}:
        return 1.15
    # Recipients and source/time adjuncts may intervene after a report.
    for j in range(max(0, len(words)-7), len(words)-1):
        verb = roots(words[j])
        tail = words[j+1:]
        if 'that' in tail or 'and' in tail or 'but' in tail:
            continue
        if verb & {'tell', 'assure', 'inform', 'notify', 'say'}:
            return 1.3
        if verb & (REPORT | THOUGHT) and (
            tail[0] in {'to', 'by', 'from', 'in', 'out', 'earlier'}
            or last.endswith('ly') or last in {'me', 'you', 'us', 'myself'}
        ):
            return 1.35
    if last == 'out' and any('turn' in roots(w) for w in words[-3:]):
        return 2.6
    pos = wordnet.parts_of_speech(last)
    categories = wordnet.categories(last)
    if 'verb' in pos and 'noun' not in pos and categories & {
        'verb.communication', 'verb.cognition', 'verb.perception'
    }:
        return 0.65
    return 0.02


def chinese_comma(clause):
    """Reports introduce a claim; ordinary clause endings are negative."""
    c = SIMPLIFY.convert(clause).strip()
    if c.endswith(tuple(FORMAL_ZH | HEARSAY_ZH)):
        return 3.7
    if c.endswith(('来说', '来看')):
        return 1.1
    if re.search(r'(提醒.{0,3}|证明)$', c):
        return 2.2
    if re.search(r'(说|称|发现|意识到|相信|看来|告诉.{0,4})$', c):
        if not c.endswith(('小说', '名称', '简称', '没说', '不说')):
            return 2.0
    if re.search(r'[”」][\p{Han}]{1,6}道$', c):
        return 1.0
    if re.search(r'(同时|首先|其次|最后|第一|第二|此外|事实上)$', c):
        return 1.0
    if re.search(r'(获悉|发现|得知)后$', c):
        return 1.1
    if re.search(r'(后|中|期间|时候|前)$', c):
        return 0.3
    if len(c) < 20 and re.search(r'(\d+[年月日号]|今天|昨天|明天|近日|目前)$', c):
        return 0.3
    if re.match(r'(据|根据|按照|依照|从|对于|关于|在)', c):
        return 0.2
    return -0.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else b''
    text = previous.decode('utf-8', 'replace')
    new = prefix.token_bytes[-1]
    token = new.decode('utf-8', 'replace')
    word = token.strip().lower()
    value = 0.0
    if word == 'that':
        words = re.findall(r"[a-z']+", text.lower())
        value = proposition(words)
        if token.strip() == 'That' and re.search(r'[.!?]\s*$', text):
            value = -0.1
    elif word == 'like':
        words = re.findall(r"[a-z']+", text.lower())[-4:]
        verbs = set().union(*(roots(w) for w in words))
        value = (1.8 if 'seem' in verbs else 1.15 if 'look' in verbs
                 else 0.8 if 'feel' in verbs else 0.9 if 'sound' in verbs
                 else -0.04)
    elif token in {',', '，', '、', '：'}:
        clause = re.split(r'[,，。;；!?:：\n]', text)[-1]
        low = clause.lower()
        if token in {',', '，', '：'} and re.search(r'\p{Han}', clause):
            value = chinese_comma(clause)
            if token == '：':
                value = max(0.15, value * 0.4)
        elif token == '、':
            value = 0.12
        if re.search(r'\baccording to\b', low):
            value = 1.3
        elif re.search(
            r'\bas (?:\w+\s+){0,3}'
            r'(shown|noted|mentioned|described|illustrated|reported|you know)\b',
            low,
        ):
            value = 0.95
    elif word in {'что', 'dass', 'hogy', 'bahwa', 'že', 'że', 'أن'}:
        value = 1.05
    elif word in {'que', 'che', 'qu'}:
        value = 0.25
    elif token in {'assistant', 'user'} and text.endswith('<|im_start|>'):
        initial_user = token == 'user' and (
            text == '<|im_start|>'
            or text.endswith('<|endoftext|><|im_start|>')
        )
        value = -0.05 if initial_user else 0.42
    else:
        zh = (SIMPLIFY.convert(token.strip())
              if re.search(r'\p{Han}', token) else '')
        if zh in HEARSAY_ZH:
            value = 3.7
        elif zh in FORMAL_ZH:
            value = 1.2
        elif zh in {'那', '那么', '这样', '所以'}:
            value = -0.8
        elif zh in {'目前', '同时'}:
            value = 0.8
        elif (text + token).endswith('ว่า'):
            value = 1.4
    if token == '<|endoftext|>':
        previous = b''
    return (doc, (previous + new)[-600:]), value

"""A short-fragment g+i detector, with a weaker g+y response.

The pair can be inside the newest token or straddle its left boundary.
Short pieces expose the spelling much more strongly than longer words do.
Latin, Greek and Cyrillic spellings are recognized. Everything else is zero.
"""
import re

READS = ()
G = 'gγг'
I = 'iιи'
PAIR = re.compile('[gγг][iιиy]')


def response(s, previous):
    lower = s.lower()
    token = lower.strip()
    match = PAIR.search(token)
    if match:
        left = match.start()
        tail = len(token) - left - 1
        vowel = token[left + 1]
        if vowel == 'y':
            return -1.0 if left == 0 and tail == 1 else 0.0
        if tail == 1:
            if left == 0:
                if token[0] == 'г':
                    return -1.8
                if s.strip().isupper() or s.strip()[0].isupper():
                    return -6.2
                return -9.2 if s[:1].isspace() else -4.8
            return -3.5 if left == 1 else (-1.5 if left == 2 else 0.0)
        if left == 0 and tail == 2:
            return -1.2
        return 0.0
    # Do not join across a space: this is a within-word spelling pattern.
    if previous and previous[-1:].lower() in G:
        if lower.startswith('.'):
            lower = lower[1:]
        if lower[:1] in I and lower:
            n = len(lower)
            if lower[0] == 'ι':
                return -7.3 if n == 1 else 0.0
            if lower[0] == 'и':
                return -3.0 if n == 1 else (-0.8 if n == 2 else 0.0)
            return -(5.8, 2.2, 1.2, 0.5)[n - 1] if n <= 4 else 0.0
        if lower == 'y':
            return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, s), response(s, previous)

"""A boundary response and a surface-form rarity/length approximation.

The first token gets a large, character-class-dependent value. Later,
English letter strings rise with rarity, especially after a space; Han
strings combine Chinese frequency and length. Other non-ASCII letters
use length. Long/tabbed whitespace has its own formatting response.
No token-specific lookup or contextual semantic analysis is attempted.
"""
from functools import lru_cache
from math import log1p, log10
import regex
from wordfreq import get_frequency_dict

READS = ()


@lru_cache(None)
def frequency(word, language):
    probability = get_frequency_dict(language).get(word.lower(), 0.0)
    return max(0.0, 9.0 + log10(probability)) if probability else 0.0


@lru_cache(None)
def predict(token, first):
    text = token.strip()
    length = len(text)
    letters = sum(c.isalpha() for c in text)
    if first:
        if letters <= 0.25 * max(1, length):
            return 3.3 if length <= 1 else 7.2
        return 6.3 if token.startswith(' ') else 8.6

    if not text:
        if '\t' in token and len(token) > 3:
            return 1.5
        if '\n' in token and len(token) > 5:
            return 1.8
        return min(1.5, max(0, len(token) - 16) * 0.025)
    if (text.isalpha() and
            len(regex.findall(r'\p{Script=Han}', text)) > length / 2):
        f = frequency(text, 'zh')
        rare = min(3.0, max(0.0, 5.0 - f))
        common = min(2.0, max(0.0, f - 5.0))
        return (-0.181 + 0.109 * rare - 0.348 * common
                + 0.746 * log1p(length))
    if length == 1:
        return 0.0 if text.isascii() else 0.15
    if text.isdigit():
        return 0.0
    if text.isalpha():
        if text.isascii():
            rarity = min(3.0, max(0.0, 5.0 - frequency(text, 'en')))
            if token.startswith(' '):
                return -0.12 + 0.54 * rarity + 0.09 * log1p(length)
            return -0.13 + 0.125 * rarity + 0.10 * log1p(length)
        return -0.38 + 0.66 * log1p(length)
    return 0.3 if text.isascii() else 0.5


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    return None, predict(prefix.token_strings[-1], first)

"""Spelling-fragment responses around f, strongest for Arabic fa (ف).

Short fa pieces and article/preposition spellings get large positive values.
Distinctive Arabic versus Persian/Urdu letter forms set the short-piece
strength. A fading trace reaches the next attached piece, especially a
vowel or vowel mark. Cyrillic ef and Japanese f-syllables are weaker;
Latin fragments include a negative vf-cluster response. Unmatched cases
are zero. Lexical exceptions and document-opening effects are omitted.
"""
import unicodedata
import regex

READS = ()
ARABIC = regex.compile(r'\p{Script=Arabic}')


def arabic_letters(text):
    return ''.join(c for c in text
                   if c.isalpha() and ARABIC.fullmatch(c))


def fa_value(letters):
    if 'ف' not in letters:
        return 0.0
    n = len(letters)
    if n == 1:
        return 4.0
    if n == 2:
        if letters in ('في', 'فى'):
            return 5.1
        if letters[-1] == 'ف' and letters[0] in 'الو':
            return 5.5
        return 3.0
    if letters == 'الف':  # definite article followed by fa
        return 6.4
    if letters == 'والف':
        return 4.0
    if letters in ('وفي', 'ففي', 'فيه', 'فيها'):
        return 4.5
    return 1.8 if n == 3 else (0.8 if n == 4 else 0.1)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    same_doc = carry and carry[0] == doc
    previous = carry[1] if same_doc else ''
    evidence = 0.95 * carry[2] if same_doc else 0.0
    # Distinctive yeh/kaf spellings identify Arabic versus Persian/Urdu.
    evidence += sum(text.count(c) for c in 'يكة')
    evidence -= sum(text.count(c) for c in 'یکپچژگےں')
    letters = arabic_letters(text)
    prev_letters = arabic_letters(previous)
    value = fa_value(letters)
    if 'ف' in letters:
        if len(letters) == 1:
            value = 5.4 if evidence > 0.5 else 2.5 if evidence < -0.5 else 4.5
        elif len(letters) == 2:
            if evidence < -0.5:
                value *= 0.5 if value > 4.0 else 0.4
            elif evidence > 0.5 and value < 4.0:
                value = 3.4
        elif evidence < -0.5:
            value *= 0.6
        if len(letters) <= 2 and not text[0].isspace():
            if prev_letters.endswith('ال'):
                value += 2.0
    # Continue only within a word, including a separately tokenized vowel mark.
    mark = text and all(unicodedata.category(c).startswith('M') for c in text)
    if (letters or mark) and not text[0].isspace() and len(letters) <= 4:
        if 'ف' in prev_letters:
            tail = len(prev_letters) - prev_letters.rindex('ف') - 1
            vowel = letters and all(c in 'اويىی' for c in letters)
            if tail == 0:
                spill = 0.8 if vowel or mark else 0.5
            else:
                spill = 0.2 if tail <= 2 else 0.0
            value += spill * fa_value(prev_letters)

    word = text.strip()
    if not letters:
        if 'ф' in word.lower() and len(word) <= 3:
            value = 0.5
        elif (previous.lower().endswith('ф') and word.isalpha()
              and not text[0].isspace()):
