        elif word == 'フ':
            value = 0.4
        elif len(word) == 2 and word[0] == 'フ' and word[1] in 'ァィェォ':
            value = 1.2 if word[1] in 'ィォ' else 0.7
        elif word.lower() == 'vf':
            value = -4.4
        elif (word.lower() == 'f' and previous.lower().endswith('v')
              and not text[0].isspace()):
            value = -3.5
        elif not text[0].isspace() and word.lower() in ('af', 'uf'):
            value = 0.6
        elif word.lower() in ('fa', 'fe', 'fi', 'fo'):
            value = 0.3
    return (doc, text, evidence), float(value)

