READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, tail = 0, '', ''
    else:
        _, position, previous, tail = carry
    value = 0.001

    if position == 0:
        if token == 'public':
            value = 1.6875
        elif token == 'private':
            value = 1.4043
        elif token == '<|endoftext|>':
            value = 0.714
        elif token.startswith('<|'):
            value = 0.10
        elif token == '\r':
            value = -0.82
        elif token == '//\n':
            value = -0.85
        elif token in {'import', 'package'}:
            value = 0.30
        elif token.startswith('#'):
            value = -0.12
        elif token and token[0] in '\"\'“':
            value = -0.12
        elif token.isascii() and token.isalpha():
            value = 0.10
        elif token.isdigit():
            value = 0.067
        elif token.isspace():
            value = 0.088
        else:
            value = 0.02
    elif position == 1 and previous == 'Title' and token == ':':
        value = -3.9601
    elif token == ' ' and tail.endswith('\\n'):
        value = -0.30
    elif token == ' ' and tail.endswith('\n'):
        value = -0.14
    elif token == ' ' and previous == '//':
        value = -0.175
    elif token == 'import':
        value = -0.20 if previous.rstrip().endswith(';') else 0.04

