"""Layer 1, MLP down-projection, component 569: a document-opening detector.

It is silent almost everywhere (typical |activation| about 0.03). It responds to the first
two tokens of a document, where the model has little context:

- The first token of a document. A bare `public` or `private` (the start of a Java or C#
  class or method) gives a strong positive value. A word opener gives a weak positive value,
  and a code or punctuation opener a weak negative one.
- The colon of a `Title:` header, when `Title` is the document's first token. That colon
  gives a large negative value, the largest activation this component has.

Documents are the runs of equal document ids in a packed row. A row's first token counts as
a document start, as the model resets its positions there.
"""

READS = ()

DOC_START_VALUES = {"public": 1.5, "private": 1.4}
WORD_OPENER = 0.1
PUNCTUATION_OPENER = -0.02
TITLE_COLON = -3.96


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_document = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_document:
        index, previous = 0, ""
    else:
        index, previous = carry[0] + 1, carry[1]
    if index == 0:
        if token in DOC_START_VALUES:
            value = DOC_START_VALUES[token]
        elif token[:1].isalpha():
            value = WORD_OPENER
        else:
            value = PUNCTUATION_OPENER
    elif index == 1 and previous == "Title" and token == ":":
        value = TITLE_COLON
    else:
        value = 0.0
    return (index, token), float(value)

