import unicodedata
import regex

READS = ()
DECLARATIONS = {'package', 'using', 'var', 'const', 'class', 'import'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    b = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        pos, first, tail = 0, b, b''
    else:
        _, pos, first, tail = carry
    text = b.decode('utf-8', 'replace')
    value = 0.002

    if len(b) == 1 and 128 <= b[0] < 192:
        ch = (tail + b).decode('utf-8', 'replace')[-1]
        name = unicodedata.name(ch, '')
        if regex.fullmatch(r'\p{Script=Han}', ch):
            value = 0.11
        elif regex.fullmatch(r'\p{Script=Hangul}', ch):
            value = 0.16
        elif regex.fullmatch(r'\p{Script=Hiragana}', ch):
            value = 0.85
        elif regex.fullmatch(r'\p{Script=Bopomofo}', ch):
            value = 1.3
        elif name.startswith('REGIONAL INDICATOR'):
            value = 1.7
        elif ch in '\x9c\x9d':
            value = -1.3
        elif unicodedata.category(ch).startswith('M'):
            value = -0.25
        else:
            value = 0.0
    elif text == '··':
        value = -0.8
    elif text == '::':
        value = -0.11
    elif text == '://':
        value = -0.17
    elif text == '    ':
        value = -0.055
    elif text in ('他', '她', '它'):
        value = -0.21

    if pos == 0:
        value = -0.28
        if text.isdigit():
            value = -0.43
        elif text.isspace():
            value = -0.55
        elif text in DECLARATIONS or text.startswith('#!'):
            value = -1.0
        elif text == '<|im_start|>':
            value = -0.11
    elif pos == 1 and first == b'1' and b == b'2':
        value = -4.24
    elif pos == 2 and first == b'1' and tail.endswith(b'12') and b == b'2':
        value = -1.68
    return (doc, pos + 1, first, (tail + b)[-8:]), value

"""An orthographic UL detector, strongest inside split or unfamiliar words.

Latin, Cyrillic and Greek letters are transliterated before looking for 'ul'.
A U at the end of one token followed by L in the next is especially strong;
continuations of an UL fragment receive a smaller echo. Common complete
words are discounted. Lowercase HTML ul tags have the opposite sign. The small
negative response at a document's start is modeled separately, as are
repeated middle-dot separators.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'de', 'es', 'it', 'pt', 'ru', 'tr', 'hu')


@lru_cache(maxsize=50000)
def roman(text):
    # Do not mistake transliterations of Han characters or syllabic scripts
    # for literal sequences of U and L letters.
    if not regex.fullmatch(r'[\p{Latin}\p{Cyrillic}\p{Greek}\P{Letter}]*', text):
        return ''
    return anyascii(text).lower()


@lru_cache(maxsize=50000)
def familiarity(word):
    """Larger wordfreq Zipf values mean more familiar words."""
    return max(zipf_frequency(word, lang) for lang in LANGUAGES)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        value = -0.48 if s.isalpha() else -0.29 if s[:1].isspace() else -0.09
        word = re.search(r'[^\W\d_]+$', s)
        return (doc, s, word[0] if word else '', s[-24:]), value

    _, previous, word, tail = carry
    n, p = roman(s), roman(previous)
    continuation = bool(regex.match(r'[\p{L}\p{M}]', s)
                        and regex.search(r'[\p{L}\p{M}]$', previous))
    text = word + s if continuation else s
    match = re.search(r'[^\W\d_]+$', text)
    new_word = match[0][-48:] if match else ''
    value = 0.003
    direct = 'ul' in n
    cross = p.endswith('u') and n.startswith('l') and continuation
    notation = tail.rstrip(" '’").endswith('U') and s.strip() == 'L'
    echo = continuation and 'ul' in p[-4:]
    if direct or cross or notation or echo:
        f = familiarity(new_word)
        if notation:
            value = 2.7
        elif cross:
            value = max(0.3, 4.2 - 0.45 * f)
        elif direct and n.lstrip().startswith('ul'):
            fragment = zipf_frequency(s.strip(), 'en')
            if f > 3.2:
                value = 2.5 if fragment > 4.6 else max(0.2, 2.0 - 0.35 * f)
            elif fragment > 1.9:
                # Vowel-bearing Latin endings, such as -ula and -uli.
                value = 3.2 if re.match(r'ul(?:[aio]|la|lo)', n.strip()) else 1.7
            else:
                value = 1.2 if continuation else 0.06
        elif direct:
            value = 0.12 if f < 5 else 0.03
        elif echo:
            strength = 1.5 if p.endswith('ul') else 0.3
            value = strength * max(0.3, 1.0 - 0.1 * f)
    if re.search(r'<\s*/?\s*ul$', tail + s):
        value = -3.5
    if len(s) > 1 and set(s) == {'·'}:
        value = -1.7
    return (doc, s, new_word, (tail + s)[-24:]), float(value)

