POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
COORDINATORS = {'and', 'or', 'but', 'nor', 'so', 'yet'}
DECLARATIONS = {'package', 'class', 'namespace', 'import'}
