Recent words vote for Portuguese against other languages using corpus word
frequencies. In Portuguese-looking text, short r/onset and nasal pieces tend
positive; contracted prepositions and demonstrative pieces tend negative.
Greek article endings have a separate negative response. Small extra rules
cover middle-dot separators and the second digit of document-initial '12'.
The weights are fitted to training activations, not token-ID lookups. This
misses finer lexical differences within each spelling/morphology class.
"""

import re
import unicodedata
from functools import lru_cache
from math import exp
from wordfreq import zipf_frequency
READS = ()
LANGUAGES = ('pt', 'en', 'es', 'fr', 'it', 'de', 'nl', 'sv', 'da',
             'nb', 'pl', 'cs', 'sk', 'hu', 'tr', 'ro', 'fi', 'id', 'vi')
@lru_cache(maxsize=60000)
def evidence(word):
    if len(word)<2 or not word.isalpha():
        return (0.,)*len(LANGUAGES)
    z=tuple(zipf_frequency(word.lower(),lang) for lang in LANGUAGES)
    best=max(z)
    if best<3:
        return (0.,)*len(LANGUAGES)
    return tuple(max(-2., x-best) for x in z)

def features(carry, token, document):
    if carry is None or carry[0]!=document:
        carry=(document, '', (0.,)*len(LANGUAGES), '', 0)
    doc, word, scores, previous, pos=carry
    # Accumulate evidence only when a word boundary closes the preceding word.
    for c in token:
        if c.isalpha():
            word+=c
        else:
            if word:
                ev=evidence(word)
                if any(ev):
                    scores=tuple(.75*a+b for a,b in zip(scores,ev))
                word=''
    # Use the current piece as provisional evidence too.
    ev=evidence(word)
    provisional=tuple(a+b for a,b in zip(scores,ev))
    mx=max(provisional)
    probs=[exp((a-mx)*1.5) for a in provisional]
    pt=(probs[0]/sum(probs))**2
    s=token.strip().lower()
    initial=bool(token[:1].isspace()) or pos==0 or previous.endswith(('\n','_','.'))
    x={'bias':1.}
    def add(k,v=1.): x[k]=v
    if token and set(token)=={'·'} and len(token)>1: add('middle_dot_run')
    if pos==1 and previous=='1' and token=='2': add('initial12')
