            if s in ('na','no','nas','nos','num','numa','nuns','numas'):
                add('n_contraction',pt)
            elif s in ('da','do','das','dos'):
                add('d_contraction',pt)
            elif s in ('dele','dela','deles','delas'):
                add('de_pronoun',pt)
            elif re.fullmatch(
                    r'(?:[dn]?ess[aeo]?s?|[dn]?ist[aeo]?s?|'
                    r'des.{0,2}|dis.{0,2}|del[ae]s?)', s):
