            elif s in ('pro','prop'): add('pro_prefix',pt)
            # Common whole words are not open consonant onsets.
            elif s in ('em','com','pela','pelo','pelas','pelos','de','se',
                       'por','para','ser','ter','ver','for','que','um','uma',
                       'tem','bem','vem','sem','a','e','o','as','os','ao','aos','ou',
                       'eu','tu','ele','ela','eles','elas','sua','seu','suas','seus',
                       'me','te','lhe','foi','era','mas','mais','como','que'):
                add('common_whole_word',pt)
