                if s in ('som','tom'):
                    add('sound_tone',pt)
                elif s in ('ar','arr'):
                    add('ar_spelling',pt)
                elif len(s)==2 and s.endswith('r') and s[0] not in 'aeiou':
                    add('r_cluster',pt)
                elif s.endswith('r') and len(s)<=3:
                    add('r_piece',pt)
                elif len(s)<=3 and s.endswith('om'):
                    add('om_piece',pt)
                elif len(s)<=3 and s.endswith('em'):
                    add('em_piece',pt)
                elif s=='n':
                    add('nasal_initial',pt)
                elif len(s)==1 and s not in 'aeiou':
                    add('single_consonant',pt)
                elif s in ('qu','gu'):
                    add('qu_onset',pt)
                else:
                    add('short_piece',pt)
            else: add('long_word',pt)
        else:
