            if s in ('esse','essa','esses','essas','ste','sta','sto',
                     'le','les','se','so','es','as') and re.fullmatch(
                            r'(?:[dn]?[eéi]ss[aeo]s?|[dn]?[eéi]st[aeo]s?|'
                            r'[dn]?aquel[ae]s?|[dn]?aquilo|del[ae]s?)',word.lower()):
