    return (doc,word,scores,token,pos+1),x

COEFFICIENTS = {
    'bias': 0.0021,
    'middle_dot_run': 1.5453,
    'initial12': 3.8283,
    'n_contraction': -1.5841,
    'd_contraction': -0.5345,
    'de_pronoun': -4.3398,
    'demonstrative_prefix': -2.4476,
    'common_whole_word': 0.0075,
    'r_cluster': 2.9581,
    'r_piece': 0.8152,
    'ar_spelling': 4.1959,
    'sound_tone': 6.3437,
    'om_piece': 0.9234,
    'em_piece': 1.7572,
    'pro_prefix': -1.1004,
    'single_consonant': 0.8846,
    'nasal_initial': -0.6524,
    'qu_onset': 1.5223,
    'short_piece': 0.2499,
    'long_word': 0.0641,
    'deictic_ending': -3.7735,
    'continuation': -0.0207,
    'greek_article_vowel': -3.3180,
    'greek_article_nu': -4.4372,
    'greek_article_ending': -2.7187,
    'greek_fused_article': -2.4888,
