READS = ()

CZECH_ACCENTS = frozenset('áéíýúůěřťďňľĺŕô')
SLAVIC_MARKERS = frozenset('ěščřžýůťďňľĺŕ')
LONG_VOWELS = frozenset('áéíóúýůô')
# Common Czech/Slovak prepositions, negation, and manner words.
FUNCTION_WORDS = {
    ' v': 1.0,       # in
    ' k': 1.2,       # towards
    ' z': 2.25,      # from / out of
    ' od': -3.5,     # from
    ' na': -1.1,     # on
    ' pod': -1.5,    # under
    ' ne': 2.35,     # not
    ' jak': 5.3,     # how
    ' tak': 3.5,     # so / thus
