def predict(text, previous, recent):
    if text == '#':
        if previous.endswith('{'):
            if previous == ' {':
                return -9.8
            return -7.0 if previous.endswith('){') else -3.2
        if previous.endswith(']('):
            return -4.2
        if previous.endswith('('):
            return -0.8
        return 0.1 if previous else 0.68
