        if len(previous) > 1 and previous.endswith('{'):
            marker = previous[-2]
            math = ('$' in recent or '\\frac' in recent
                    or '\\left' in recent)
            if marker == '$':
                return -5.4
            if marker == '(':
                return -5.2 if math else -3.3
            if marker in ',:':
                return -4.1
            if marker == '{':
                return -3.4
            if marker in '})]=':
                return -2.5
            if marker in '_^':
                return -0.55
        if len(previous) > 1 and previous.endswith('('):
            return -0.9
        return 0.04
    if text == '!' and previous.endswith('{'):
        return -4.5

    lower = text.lower()
    if lower in FUNCTION_WORDS and any(c in SLAVIC_MARKERS for c in recent):
        return FUNCTION_WORDS[lower]

    word = lower.strip()
    if word and len(word) <= 2 and word[0] in 'čšž':
        consonant = word[0]
        accented = any(c in CZECH_ACCENTS for c in recent)
        if len(word) == 2:
            if word[1] in 'aeiouyáéíóúýěů':
                return 1.7 if consonant == 'š' else 0.7
            return 3.5 if accented else 1.5
        if text.startswith(' ') and consonant in 'čž':
            return 5.7 if accented else 2.8
        if not text.startswith(' ') and previous[-1:].lower() in LONG_VOWELS:
            return {'č': 1.8, 'š': 0.5, 'ž': 1.5}[consonant]
        if accented:
            return {'č': 4.0, 'š': 3.65, 'ž': 4.3}[consonant]
        return {'č': 1.4, 'š': 0.1, 'ž': 1.4}[consonant]
    return 0.002


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        previous, recent = '', ''
    else:
        _, previous, recent = carry
    value = predict(text, previous, recent)
    recent = (recent + text.lower())[-192:]
    return (document, text, recent), value

programs.haiku:
"""Czech/Slovak háček letters fire positive (strongest on č and ž); markup openers
fire negative: a '#' link anchor or a LaTeX backslash right after an opening bracket."""
HACEK = {"č": 4.0, "ž": 4.0, "š": 3.0, "ř": 1.0, "ď": 2.0, "ť": 1.0, "ň": 1.0, "ľ": 0.5, "ě": 0.5, "ż": 2.0}
READS = ()

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    v = 0.0
    if s in HACEK:
        v = HACEK[s]
    elif s == "#" and prev.endswith("{"):
        v = -9.0
    elif s == "#" and prev.endswith(("(", "[")):
        v = -4.0
    elif s == "\\" and prev.endswith(("{", "(")) and not prev.endswith("_{"):
        v = -4.0
    elif s == "\\" and prev.endswith("_{"):
        v = -0.5
    return None, v
